/* ============================================================
   SHEET / SCRIM UTIL
   ============================================================ */
function showSheet(id){
  document.getElementById("scrim").classList.add("show");
  document.getElementById(id).classList.add("show");
}
function closeAllSheets(){
  document.getElementById("scrim").classList.remove("show");
  document.querySelectorAll(".sheet").forEach(s=>s.classList.remove("show"));
}
function closeFullscreen(id){ document.getElementById(id).classList.remove("show"); }

/**
 * Puts a "Back to Home" on every full-screen print layout.
 *
 * Every ordinary screen already has one; the print layouts had only a bare
 * ✕, which closes the layout but leaves you wherever you happened to be —
 * so getting home from a printed bill meant two guesses instead of one tap.
 *
 * Done once over every .fullscreen rather than by editing each layout's
 * markup, so a print layout added later cannot quietly miss out. The link
 * sits inside .fs-bar, which the print stylesheet hides, so it can never
 * reach the paper.
 */
/**
 * Opens a printable document in its own tab, with a way back.
 *
 * These documents are written into a blank tab, so none of the app is around
 * them — on a phone that leaves you stranded on a sheet of paper with no
 * Home, no Back, and only the browser's tab switcher to escape with. The bar
 * added here is the way out, and it is screen-only: it never reaches paper.
 *
 * Closing works because the tab was opened by script, which is what permits
 * window.close(). If a browser ever refuses, the button falls back to going
 * back in history rather than doing nothing.
 */
function openPrintWindow(html, opts){
  const label = (opts && opts.title) || "Document";
  const bar = `
    <style>
      .pw-bar{position:sticky;top:0;z-index:99;display:flex;gap:8px;align-items:center;
        background:#1b2a4a;color:#fff;padding:10px 12px;font:600 13px -apple-system,
        BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;}
      .pw-bar button{font:inherit;border:0;border-radius:999px;padding:7px 13px;cursor:pointer;}
      .pw-back{background:rgba(255,255,255,.18);color:#fff;}
      .pw-print{background:#e8b530;color:#1b2a4a;}
      .pw-ttl{opacity:.75;font-weight:500;margin-left:2px;}
      @media print{ .pw-bar{display:none !important;} }
    </style>
    <div class="pw-bar">
      <button class="pw-back" onclick="window.close();setTimeout(function(){history.back();},120)">&larr; Back</button>
      <button class="pw-print" onclick="window.print()">Print</button>
      <span class="pw-ttl">${label}</span>
    </div>`;

  /* Inserted right after <body> so it is the first thing on screen. If the
     document has no body tag for any reason, it simply goes in front. */
  const withBar = /<body[^>]*>/i.test(html)
    ? html.replace(/(<body[^>]*>)/i, "$1" + bar)
    : bar + html;

  const w = window.open("", "_blank");
  if(!w){ toast("Your browser blocked the print window. Allow pop-ups for this app."); return null; }
  w.document.write(withBar);
  w.document.close();
  return w;
}

/**
 * Hides what only the owner should see — the margin reports.
 *
 * This is tidiness, not security. Every one of these endpoints refuses a
 * staff login on the server, so removing the button only saves someone from
 * pressing something that would say no.
 */
function applyOwnerOnlyVisibility(){
  const owner = isOwner();
  document.querySelectorAll(".owner-only").forEach(el => {
    el.style.display = owner ? "" : "none";
  });
}

function installFullscreenHomeLinks(){
  document.querySelectorAll(".fullscreen").forEach(fs => {
    /* The Print Engine's bar is two stacked rows — a title row and a row of
       controls. The link belongs beside the title, not above both, so the
       inner row is preferred where there is one. */
    const bar = fs.querySelector(".pe-bar-top") || fs.querySelector(".fs-bar");
    if(!bar || bar.querySelector(".fs-home")) return;

    const link = document.createElement("button");
    link.className = "fs-home";
    link.type = "button";
    link.innerHTML = "&larr; Home";
    link.addEventListener("click", ()=>{
      closeFullscreen(fs.id);
      // Sheets can be open on top of a preview (Void, Share, E-Way Bill);
      // leaving one behind would land you on Home with a stray panel up.
      closeAllSheets();
      switchTab("home");
    });
    bar.prepend(link);
  });
}

/* ============================================================
   SUBSCRIPTION
   On an unlicensed build (no vendor public key compiled in) every
   one of these is a no-op, so nothing changes for a shop running
   its own copy.
   ============================================================ */
async function refreshLicenseBanner(){
  try{ state.license = await api("GET","/license"); }
  catch(e){ return; }
  const st = state.license;
  let bar = document.getElementById("license-bar");
  if(!st || !st.enforced || st.status === "active"){ if(bar) bar.remove(); return; }
  if(!bar){
    bar = document.createElement("div");
    bar.id = "license-bar";
    bar.style.cssText = "padding:10px 16px;font-size:12px;font-weight:700;text-align:center;cursor:pointer;";
    document.getElementById("app").prepend(bar);
    bar.addEventListener("click", ()=>openSettings());
  }
  const bad = st.expired;
  bar.style.background = bad ? "var(--danger)" : "var(--gold)";
  bar.style.color = bad ? "#fff" : "var(--navy)";
  /* Worded from the state rather than assuming expiry: a copy blocked
     because it cannot reach the licence server has not expired, and
     telling its owner to renew sends them to their supplier with the
     wrong question. */
  bar.textContent = bad
    ? `${st.message} Read-only until this is sorted out — tap for details.`
    : `${st.message} Tap for details.`;
}
/* The subscription box in Settings.
 *
 * Two shapes, because a copy is sold under one of two schemes and the
 * wording has to match what the shopkeeper was actually handed. Asking for
 * a "licence key" when their supplier sent a short code is how a support
 * call starts.
 *
 *   mode "server" — they were given an activation code. The subscription
 *                   lives in the supplier's panel and can be withdrawn.
 *   mode "key"    — older copies, given a long signed key to paste.
 *
 * Hidden entirely in the shop's own copy, where nothing is enforced.
 */
function licenseSettingsHtml(){
  const st = state.license;
  if(!st || !st.enforced) return "";

  const bad = st.blocked || st.expired;
  const colour = bad ? "var(--danger)"
               : (st.status === "expiring" || st.status === "active-cached") ? "var(--gold)"
               : "var(--ok)";

  if(st.mode === "server"){
    const facts = [
      st.licensedTo ? `Licensed to ${escapeHtml(st.licensedTo)}` : "",
      st.expiresOn
        ? `Valid until ${escapeHtml(st.expiresOn)}${st.daysLeft != null ? ` — ${st.daysLeft} day${st.daysLeft === 1 ? "" : "s"} left` : ""}`
        : "",
      st.code ? `Activation code ${escapeHtml(st.code)}` : "",
      st.lastConfirmedDaysAgo != null
        ? `Last confirmed ${st.lastConfirmedDaysAgo === 0 ? "today" : st.lastConfirmedDaysAgo + " day(s) ago"}`
        : ""
    ].filter(Boolean);

    /* The box to type a code into appears only when there is no working
       subscription. A copy that is running fine has nothing to type, and an
       empty box invites somebody to try. */
    const needsCode = !st.code || st.status === "needs-activation" || st.status === "not-approved";

    return `
    <div class="section-title" style="margin-top:18px;">Subscription</div>
    <div class="card" id="st-lic-card" style="border-left:3px solid ${colour};">
      <div style="font-size:12px;font-weight:700;">${escapeHtml(st.message || "")}</div>
      ${facts.map(f => `<div class="muted" style="font-size:11px;margin-top:2px;">${f}</div>`).join("")}
      ${needsCode ? `
        <label class="field-label" style="margin-top:10px;">Activation code</label>
        <input type="text" id="st-activation" placeholder="ABCD-EFGH-JKLM"
               autocapitalize="characters" spellcheck="false"
               style="letter-spacing:.08em;font-weight:700;">
        <button class="btn btn-primary" id="st-activate" style="margin-top:10px;">Activate</button>
        <div class="muted" style="font-size:11px;margin-top:6px;">
          Your supplier gives you this code. It is not a password — it only says
          which subscription this copy belongs to.
        </div>` : `
        <button class="btn btn-outline" id="st-recheck" style="margin-top:10px;">Check again now</button>
        <div class="muted" style="font-size:11px;margin-top:6px;">
          This copy confirms its subscription on its own every few hours.
          Use this if you have just renewed.
        </div>
        <a href="#" id="st-newcode" class="btn-danger-link"
           style="display:inline-block;margin-top:10px;font-size:11.5px;">Enter a different code</a>`}
    </div>`;
  }

  /* The older scheme: one long signed key, pasted in. */
  return `
    <div class="section-title" style="margin-top:18px;">Subscription</div>
    <div class="card" style="border-left:3px solid ${colour};">
      <div style="font-size:12px;font-weight:700;">${escapeHtml(st.message || "")}</div>
      ${st.licensedTo ? `<div class="muted" style="font-size:11px;margin-top:2px;">Licensed to ${escapeHtml(st.licensedTo)}</div>` : ""}
      <label class="field-label" style="margin-top:10px;">Licence key</label>
      <input type="text" id="st-license" placeholder="Paste the key you were sent">
      <button class="btn btn-primary" id="st-license-save" style="margin-top:10px;">Activate</button>
    </div>`;
}
function wireLicenseSettings(){
  /* --- the activation-code scheme --- */
  const act = document.getElementById("st-activate");
  if(act) act.addEventListener("click", async ()=>{
    const code = (document.getElementById("st-activation").value || "").trim();
    if(!code){ toast("Enter the code your supplier gave you."); return; }
    act.disabled = true;
    const wasA = act.textContent;
    act.textContent = "Checking…";
    try{
      await api("POST", "/license/activate", { code });
      state.license = await api("GET", "/license");
      await refreshLicenseBanner();
      toast("Activated.", "ok");
      closeAllSheets();
    }catch(e){
      toast(e.message);
      act.disabled = false;
      act.textContent = wasA;
    }
  });

  const recheck = document.getElementById("st-recheck");
  if(recheck) recheck.addEventListener("click", async ()=>{
    recheck.disabled = true;
    const wasR = recheck.textContent;
    recheck.textContent = "Checking…";
    try{
      const r = await api("POST", "/license/recheck");
      state.license = await api("GET", "/license");
      await refreshLicenseBanner();
      toast(r.ok ? "Subscription confirmed."
                 : `Could not reach the licence server: ${r.error}`, r.ok ? "ok" : "");
    }catch(e){ toast(e.message); }
    recheck.disabled = false;
    recheck.textContent = wasR;
  });

  const newCode = document.getElementById("st-newcode");
  if(newCode) newCode.addEventListener("click", (e)=>{
    e.preventDefault();
    /* Swaps the box in place and saves nothing. The subscription this copy
       is running on keeps working until a new code is actually accepted —
       clearing it first would take a working shop offline to type. */
    const card = document.getElementById("st-lic-card");
    if(!card) return;
    card.innerHTML =
      `<label class="field-label" style="margin-top:0;">Activation code</label>` +
      `<input type="text" id="st-activation" placeholder="ABCD-EFGH-JKLM" ` +
      `autocapitalize="characters" spellcheck="false" style="letter-spacing:.08em;font-weight:700;">` +
      `<button class="btn btn-primary" id="st-activate" style="margin-top:10px;">Activate</button>` +
      `<div class="muted" style="font-size:11px;margin-top:6px;">` +
      `The subscription this copy is using now keeps working until a new code is accepted.</div>`;
    wireLicenseSettings();
  });
  const btn = document.getElementById("st-license-save");
  if(!btn) return;
  btn.addEventListener("click", async ()=>{
    const key = document.getElementById("st-license").value.trim();
    if(!key){ toast("Paste the licence key first."); return; }
    btn.disabled = true;
    try{
      state.license = await api("POST","/license",{ key });
      await refreshLicenseBanner();
      closeAllSheets();
      toast(state.license.message, "ok");
      await renderAll();
    }catch(err){ toast(err.message); }
    finally{ btn.disabled = false; }
  });
}

/* ============================================================
   INVOICE PREVIEW
   ============================================================ */
/**
 * Named @page rules with a `page:` property per element are unreliable
 * across browsers (especially the Android Chrome most staff will actually
 * print from), so the selected paper size's @page block is injected fresh
 * here instead — always exactly one @page rule in effect at print time.
 */
function applyPageSizeStyle(){
  const style = document.getElementById("page-size-style");
  if(!style) return;
  const isA4 = state.paperSize === "A4";
  const pageH = isA4 ? 297 : 210, margin = isA4 ? 6 : 3;
  // A real safety margin, not just the @page margin — a physical printer's
  // own default margins, "shrink to fit" being off, or a paper-size
  // mismatch (Letter vs A4) can all shrink the actual printable area below
  // what @page alone promises. Targeting slightly less than the full
  // theoretical content height means real content that measures as exactly
  // fitting on screen still has room to spare once it hits a real printer,
  // instead of spilling one line onto a second page.
  //
  // These were 4mm/5mm, which left an A5 page rendering at exactly 200mm
  // against 204mm of theoretical printable area. That ~4mm of slack is
  // thinner than the non-printable edge most inkjet/laser trays actually
  // have (typically 4-6mm), and thinner still once Chrome's own header/
  // footer band is on — so a perfectly normal one-item invoice tipped onto
  // a second sheet. 14mm leaves room for the printer's hardware margin AND
  // a header/footer, while the page still visually fills the sheet.
  // 14mm on top of the @page margin left a quarter of the sheet blank below
  // the terms — the bill visibly stopped short of the bottom. The @page
  // margin already IS the printer's safety; this only guards against
  // rounding and a browser's own header/footer band, so 5mm is enough.
  // A4 now targets 285mm of a 297mm sheet instead of 271mm.
  const safetyBuffer = 5;
  const contentH = pageH - margin * 2 - safetyBuffer;
  // min-height fills the whole sheet, Tally-style, even with just one item —
  // the table's flex-grow (see .erp-table-wrap) is what actually stretches
  // to reach it. flex-shrink stays disabled everywhere in this chain so a
  // LONG item list is still free to grow past one page rather than being
  // squeezed to fit (that was the "shit" print the row-shrinking caused).
  style.textContent = `
    @page{ size:${isA4 ? "A4" : "A5"} portrait; margin:${margin}mm; }
    .invoice-page{ min-height:${contentH}mm; }
  `;
}
/**
 * Browser Print, guaranteed to come out on ONE page.
 *
 * window.print() on its own leaves the outcome to whatever the browser and
 * the printer settings happen to do, which is how a bill that measured as
 * fitting still arrived on two sheets: Chrome's own header/footer band, a
 * tray loaded with Letter instead of A4, or "shrink to fit" being off all
 * eat into the printable area after our measuring is done.
 *
 * So the page is measured against the real printable height and, if it is
 * over, shrunk to fit before printing. `zoom` is the lever rather than a
 * transform because Chrome applies zoom during LAYOUT, so pagination sees
 * the smaller size — a transform only scales the pixels and the browser
 * still breaks the page where the unscaled content ended.
 *
 * A floor of 0.55 stops a very long bill being reduced to something nobody
 * can read; past that it is allowed onto a second sheet, and the operator
 * is told rather than left to discover it at the printer.
 */
function printInvoiceOnePage(){
  const page = document.getElementById("invoice-page-content");
  if(!page){ window.print(); return; }

  const isA4 = state.paperSize === "A4";
  const pageH = isA4 ? 297 : 210, margin = isA4 ? 6 : 3;
  const MM_TO_PX = 96 / 25.4;
  // The @page margin is the only thing between content and the sheet edge,
  // so the printable height is the sheet less both margins.
  const availablePx = (pageH - margin * 2) * MM_TO_PX;

  const previousZoom = page.style.zoom;
  page.style.zoom = "";                       // measure unscaled
  const naturalPx = page.scrollHeight;

  /* Converged, not calculated in one shot.
     Shrinking reflows the page — text rewraps, rows change height — so the
     result of a single available/natural division is not what you get. The
     first attempt measured 295mm where the arithmetic promised 284. So:
     apply, measure what really happened, correct, repeat. Four passes is
     ample; each one lands much closer than the last. */
  /* ONE PAGE, ALWAYS.

     There used to be a floor at 0.55: below that the bill was allowed to
     spill onto a second sheet on the grounds that smaller was unreadable.
     That is not the trade the shop wants — a bill must come out on one
     sheet whatever it costs in size, so the floor is gone and the fit
     keeps converging until it lands.

     Still converged rather than divided once: shrinking reflows the page,
     text rewraps and rows change height, so a single available/natural
     division is not what you get. An early attempt asked for 284mm and
     rendered 295. Passes are raised from four to six because without a
     floor the search can start much lower and needs the extra room to
     settle. */
  let note = "";
  const TINY = 0.45;          // below this the print is legible but small
  let finalScale = 1;
  if(naturalPx > availablePx + 1){
    let scale = availablePx / naturalPx;
    for(let pass = 0; pass < 6; pass++){
      page.style.zoom = String(Math.floor(scale * 1000) / 1000);
      // Real rendered height, in the same device pixels as availablePx.
      const actualPx = page.getBoundingClientRect().height;
      finalScale = scale;
      if(actualPx <= availablePx) break;
      scale *= availablePx / actualPx;
    }
    /* A last hard squeeze. Six passes converge on almost anything, but a
       bill with a very long item list can still be a hair over, and a hair
       over is a second sheet with three lines on it. */
    let guard = 0;
    while(page.getBoundingClientRect().height > availablePx && guard++ < 12){
      finalScale *= 0.96;
      page.style.zoom = String(Math.floor(finalScale * 1000) / 1000);
    }
    if(finalScale < TINY){
      // It fits, as asked — but say so, because the operator should learn
      // it from the screen rather than from squinting at the paper.
      note = "This bill has a lot of items — it fits one page, but the print is small.";
    }
  }

  const restore = () => { page.style.zoom = previousZoom; window.removeEventListener("afterprint", restore); };
  window.addEventListener("afterprint", restore);
  // afterprint does not fire in every browser; this is the belt to its braces
  // so the preview is never left shrunk on screen.
  setTimeout(restore, 3000);

  if(note) toast(note);
  window.print();
}

function setPaper(size){
  state.paperSize = size;
  document.getElementById("paper-a5").classList.toggle("selected", size==="A5");
  document.getElementById("paper-a4").classList.toggle("selected", size==="A4");
  applyPageSizeStyle();
  renderInvoicePageContent();
}
let lastPreviewInvoice = null;
function openInvoicePreview(existingInvoice){
  if(!existingInvoice && !state.cart.length){ toast("Add items to the invoice first."); return; }
  // Re-read on every open so a template edited in the Designer shows on the
  // very next bill, then redraw once it lands.
  loadBillTemplates().then(() => { if(lastPreviewInvoice) renderInvoicePageContent(); });
  setTimeout(renderInvoiceGstPanel, 0);   // after lastPreviewInvoice is set
  /* The shop's saved paper preference SEEDS the session here, once, so it is
     what a preview opens on — while the A4 / A5 buttons and the print panel
     stay free to change it for this bill without the seed fighting back. */
  const savedPaper = billPrefs().paper;
  if(savedPaper && savedPaper !== state.paperSize) setPaper(savedPaper);
  if(existingInvoice){
    lastPreviewInvoice = existingInvoice;
  } else {
    const t = computeTotals();
    lastPreviewInvoice = {
      challan_no: "(unsaved preview)", date: isoDate(new Date()),
      doc_type: state.docType,
      customer_id: state.selectedCustomerId,
      // Shape matches a row from the API so one template renders both an
      // unsaved preview and a saved invoice re-opened from history.
      items: state.cart.map(c=>{
        const r = lineCalc(c);
        const p = state.products.find(p=>p.id===c.productId);
        return {
          name:c.name, code:(p&&p.code)||"", brand:(p&&p.brand)||"", hsn_code:(p&&p.hsn_code)||"",
          gst_rate:c.gstRate||0,
          mode:r.mode, size_label:r.sizeLabel,
          length_ft:r.lengthFt, width_val:r.widthVal, thickness_in:r.thicknessIn,
          pieces:r.pieces, per_piece:r.perPiece, unit_label:r.unit,
          // Named as the database names it, because the print renderer reads
          // saved bills and unsaved previews through exactly the same code.
          qty:r.billedQty, rate:r.rate, discount_pct:r.discountPct || 0
        };
      }),
      tax_type: t.taxType, discount_amount:t.discount, subtotal:t.subtotal,
      cgst:t.cgst, sgst:t.sgst, igst:t.igst,
      transport:t.transport, loading:t.loading, round_off:t.roundOffAmount,
      total:t.total, advance:t.advance, balance_due:t.balanceDue,
      delivery_man: state.deliveryMan || "",
      vehicle_number: state.vehicleNumber || "",
      delivery_address: state.deliveryAddress || "",
      remarks: state.remarks || ""
    };
  }
  const challan = lastPreviewInvoice.doc_type === "challan";
  const fsTitle = document.querySelector("#fs-invoice .fs-title");
  if(fsTitle) fsTitle.textContent = challan ? "Delivery Challan" : "Invoice Preview";

  // "Delivery Challan (With Rate)" vs "(Without Rate)" is a PRINT-TIME choice
  // on the same saved document — the item rate is stored either way (see
  // server/routes/invoices.js), this toggle only controls whether it's shown.
  // Resets to off (the original, still-default behaviour) each time a fresh
  // challan is opened, rather than remembering the last choice.
  const toggleRow = document.getElementById("challan-rate-toggle-row");
  if(toggleRow){
    toggleRow.style.display = challan ? "flex" : "none";
    // REFLECTS the current choice rather than forcing it back to "without
    // rate". The same toggle now also sits on the Billing screen, so a choice
    // made before saving has to survive into the preview — resetting here
    // would silently undo it the moment the challan opened. A fresh challan
    // still starts at "Without Rate" (see setDocType and the post-save reset).
    toggleRow.querySelectorAll("[data-challan-rate]").forEach(b=>{
      b.classList.toggle("selected", (b.dataset.challanRate === "true") === !!state.challanShowRate);
      b.onclick = () => {
        state.challanShowRate = b.dataset.challanRate === "true";
        toggleRow.querySelectorAll("[data-challan-rate]").forEach(x=>
          x.classList.toggle("selected", x === b));
        syncBillingChallanRateChips();
        renderInvoicePageContent();
      };
    });
  }

  // Silent printing needs a real, saved invoice to look up server-side — an
  // unsaved live preview (still being composed) has nothing to print yet.
  const serverPrintBtn = document.getElementById("inv-server-print");
  const statusRow = document.getElementById("print-status-row");
  if(statusRow){ statusRow.style.display = "none"; statusRow.textContent = ""; }
  if(serverPrintBtn){
    const canPrint = !!(existingInvoice && existingInvoice.id);
    serverPrintBtn.disabled = !canPrint;
    serverPrintBtn.title = canPrint ? "" : "Complete the sale first — printing needs a saved invoice.";
  }

// Remove any edit/void/delete buttons left over from a previously-opened
// document before deciding which ones this one needs — the set differs by
// doc type and whether it's already voided.
["inv-edit", "inv-void", "inv-delete", "inv-return", "inv-convert", "inv-ack"].forEach(id => { const el = document.getElementById(id); if(el) el.remove(); });
  if(existingInvoice && existingInvoice.id && !existingInvoice.voided){
    const actionsBar = document.querySelector(".inv-actions");
    const editBtn = document.createElement("button");
    editBtn.id = "inv-edit"; editBtn.textContent = "✎ Edit";
    editBtn.onclick = ()=>{ closeFullscreen("fs-invoice"); editExistingInvoice(existingInvoice); };
    actionsBar.appendChild(editBtn);

    if(challan){
      // Ticking off the signed Office Copy coming back from the customer.
      const isReceived = existingInvoice.ack_status === "Received";
      const ackBtn = document.createElement("button");
      ackBtn.id = "inv-ack";
      ackBtn.textContent = isReceived ? "🟢 Received — undo" : "🟡 Mark as Received";
      ackBtn.onclick = async ()=>{
        try{
          if(isReceived){
            if(!confirm(`Mark ${existingInvoice.challan_no} back as Pending acknowledgement?`)) return;
            await api("POST", `/invoices/${existingInvoice.id}/acknowledge`, { received:false });
            toast("Marked back as Pending.", "ok");
          } else {
            const who = prompt("Who signed the Office Copy? (optional — leave blank to just mark it received)") ;
            if(who === null) return;   // cancelled
            await api("POST", `/invoices/${existingInvoice.id}/acknowledge`, { received:true, receiverName: who });
            toast("Challan marked as Received.", "ok");
          }
          closeFullscreen("fs-invoice");
          if(state.reportType==="Challan") await renderReport();
        }catch(err){ toast(err.message); }
      };
      actionsBar.appendChild(ackBtn);
    }

    if(!challan){
      const returnBtn = document.createElement("button");
      returnBtn.id = "inv-return"; returnBtn.textContent = "Return Items";
      returnBtn.onclick = ()=>{ closeFullscreen("fs-invoice"); openSalesReturn(existingInvoice); };
      actionsBar.appendChild(returnBtn);
    } else if(!existingInvoice.converted_invoice_id){
      const convertBtn = document.createElement("button");
      convertBtn.id = "inv-convert"; convertBtn.textContent = "Convert to Invoice";
      convertBtn.onclick = async ()=>{
        if(!confirm(`Raise a Tax Invoice for ${existingInvoice.challan_no}? This bills the customer for goods already delivered — it will NOT touch stock again, but will add to the customer's due.`)) return;
        try{
          const result = await api("POST", `/invoices/${existingInvoice.id}/convert-to-invoice`, {});
          await loadCustomers();
          closeFullscreen("fs-invoice");
          toast(`Converted to ${result.invoice.challan_no}.`, "ok");
        }catch(err){ toast(err.message); }
      };
      actionsBar.appendChild(convertBtn);
    }
  }
  if(existingInvoice && existingInvoice.id && isOwner()){
    const actionsBar = document.querySelector(".inv-actions");
    const afterDelete = async (msg) => {
      toast(msg, "ok");
      closeFullscreen("fs-invoice");
      await Promise.all([loadProducts(), loadCustomers()]);
      await renderHome();
    };

    if(challan){
      // A Delivery Challan carries no GST or financial record worth
      // preserving, so it only gets a real Delete — Void's benefit (keeping
      // a numbered record intact) doesn't apply here.
      const del = document.createElement("button");
      del.id = "inv-delete"; del.textContent = "Delete Challan";
      del.onclick = async ()=>{
        if(!confirm("Delete this challan? Stock will be restored and this cannot be undone.")) return;
        try{ await api("DELETE", `/invoices/${lastPreviewInvoice.id}`); await afterDelete("Challan deleted."); }
        catch(err){ toast(err.message); }
      };
      actionsBar.appendChild(del);
    } else {
      // A Tax Invoice/Estimate is a numbered GST record — Void (reverses
      // stock/dues, keeps the record marked voided) is the button to reach
      // for. Delete is offered too, but only with a much sharper warning:
      // it leaves a gap in the SP0000001... sequence, which can look
      // irregular in a GST audit.
      const voidBtn = document.createElement("button");
      voidBtn.id = "inv-void"; voidBtn.textContent = "Void Invoice";
      voidBtn.onclick = async ()=>{
        if(!confirm("Void this invoice? Stock and customer dues will be reversed. The record stays visible as voided.")) return;
        try{
          await api("POST", `/invoices/${lastPreviewInvoice.id}/void`);
          await afterDelete("Invoice voided.");
        }catch(err){ toast(err.message); }
      };
      actionsBar.appendChild(voidBtn);

      const del = document.createElement("button");
      del.id = "inv-delete"; del.textContent = "Delete Invoice";
      del.onclick = async ()=>{
        if(!confirm(`Permanently delete ${lastPreviewInvoice.challan_no}? Stock and customer dues will be reversed, and the record will be GONE — not just voided. This leaves a gap in your estimate number sequence, which can look irregular in a GST audit. This cannot be undone.`)) return;
        try{ await api("DELETE", `/invoices/${lastPreviewInvoice.id}`); await afterDelete("Invoice deleted."); }
        catch(err){ toast(err.message); }
      };
      actionsBar.appendChild(del);
    }
  }
  // Sheet must be visible (display:none has no layout box at all) BEFORE
  // setPaper()'s render measures real element heights to decide how many
  // blank filler rows the table needs — measuring while hidden reads 0 for
  // everything, which previously ran away adding thousands of rows.
  document.getElementById("fs-invoice").classList.add("show");
  setPaper(state.paperSize);
}
async function openExistingInvoice(invoiceId){
  try{
    const inv = await api("GET", `/invoices/${invoiceId}`);
    inv.customer_id = inv.customer_id;
    openInvoicePreview(inv);
  }catch(e){ toast(e.message); }
}
/* Printed-document themes. Classic carries NO class — it is the layout in
   style.css that this app has always printed, so a shop that never touches
   the setting sees no change at all. The others are additive colour/border
   overrides (.theme-tally / .theme-navy / .theme-minimal). */
const PRINT_THEMES = [
  { id:"classic", name:"Classic",      desc:"The standard layout — black rules, teal item grid." },
  { id:"tally",   name:"Tally Style",  desc:"Everything ruled in black, double lines, grey table head." },
  { id:"navy",    name:"Navy & Gold",  desc:"Matches your Quotation template — navy header, gold accents." },
  { id:"minimal", name:"Minimal",      desc:"Hairline rules, no boxes, lots of white space. Uses less ink." },
  // A LAYOUT, not a colour scheme — its own markup, with the HSN/SAC tax
  // summary, declaration and bank block a Tally invoice carries. Classic
  // stays exactly as it is; switching back returns it unchanged.
  { id:"tallyfull", name:"Tally Format", desc:"Full Tally-style tax invoice — ruled party grid, HSN/SAC tax summary, declaration and bank details." }
];
const THEME_IDS = PRINT_THEMES.map(t=>t.id);

/** Which theme a document prints in. Invoice and Challan are set separately,
 *  so a shop can print formal Tally-style invoices while challans stay plain.
 *  An unknown stored value falls back to classic rather than printing with no
 *  theme rules at all. */
function printThemeFor(challan){
  const cfg = state.settings || {};
  const t = challan ? cfg.challan_theme : cfg.invoice_theme;
  return THEME_IDS.includes(t) ? t : "classic";
}

function applyPrintTheme(el, challan){
  THEME_IDS.forEach(id => el.classList.remove("theme-"+id));
  const t = printThemeFor(challan);
  if(t !== "classic") el.classList.add("theme-"+t);
  return t;
}

/* ============================================================
   THE PRINTED BILL

   One layout, driven by Bill Print Settings. Which columns appear, whether
   rates print, the paper size and the wording all come from `billPrefs()`;
   the figures themselves always come from the saved document, never from the
   print panel. That split is the whole design: the panel decides what is
   SHOWN, and can never change what is OWED.
   ============================================================ */

/* Every column the item table can carry, in printing order.
   `show` reads the saved preferences; `cell` renders one line. Adding a
   column here is the only edit needed — the header, the body and the blank
   filler rows below are all generated from this one list, so they can never
   disagree about how many columns there are. */
function billColumns(ctx){
  const p = ctx.prefs, money = v => ctx.showRate ? fmtMoney(v) : "";
  return [
    { key:"sn",     label:"Sr.",                cls:"c-sn",   show:p.cols.sn,
      cell:(it,i)=>String(i+1) },
    { key:"name",   label:"Item Name",          cls:"c-name", show:p.cols.name,
      cell:it=>escapeHtml(it.name) },
    { key:"size",   label:"Size / Description", cls:"c-size", show:p.cols.size,
      cell:it=>escapeHtml(it.size_label || "") },
    { key:"qty",    label:"Qty",                cls:"c-qty num", show:p.cols.qty,
      cell:it=>billQtyCell(it) },
    { key:"unit",   label:"Unit",               cls:"c-unit", show:p.cols.unit,
      cell:it=>escapeHtml(billUnitOf(it)) },
    { key:"rate",   label:"Rate",               cls:"c-rate num", show:p.cols.rate,
      cell:it=>money(it.rate) },
    { key:"disc",   label:"Disc.%",             cls:"c-disc num", show:p.cols.disc,
      cell:it=>ctx.showRate ? Number(it.discount_pct || 0).toFixed(2) : "" },
    { key:"taxable",label:"Taxable Amt",        cls:"c-taxable num", show:p.cols.taxable,
      cell:it=>money(billLineNet(it)) },
    { key:"cgst",   label:"CGST",               cls:"c-cgst num", show:p.cols.cgst && ctx.gstEnabled && !ctx.isIGST,
      cell:it=>money(billLineTax(it) / 2) },
    { key:"sgst",   label:"SGST",               cls:"c-sgst num", show:p.cols.sgst && ctx.gstEnabled && !ctx.isIGST,
      cell:it=>money(billLineTax(it) / 2) },
    { key:"igst",   label:"IGST",               cls:"c-igst num", show:p.cols.igst && ctx.gstEnabled && ctx.isIGST,
      cell:it=>money(billLineTax(it)) },
    { key:"amount", label:"Amount",             cls:"c-amt num", show:p.cols.amount,
      cell:it=>money(billLineNet(it)) }
  ].filter(c=>c.show);
}

/** Gross line value, before its own discount. */
function billLineGross(it){ return round2((Number(it.qty)||0) * (Number(it.rate)||0)); }
/** What the line is actually worth after its own discount — the figure the
 *  Amount column shows and the subtotal sums. */
function billLineNet(it){
  return round2(billLineGross(it) * (1 - (Number(it.discount_pct)||0)/100));
}
/** This line's share of GST, at its own rate, on its own discounted value. */
function billLineTax(it){
  return round2(billLineNet(it) * ((Number(it.gst_rate)||0)/100));
}
function billUnitOf(it){
  const mode = it.mode || "UNIT";
  return it.unit_label || (Pricing.MODES[mode] && Pricing.MODES[mode].unit) || "";
}
/* Area and length items bill in a different unit from the physical piece
   count — 4 sheets at 8x4ft is 32 Sq.ft — so both are shown, or "32" reads
   as a mismatch against a delivery of 4. */
function billQtyCell(it){
  const mode = it.mode || "UNIT";
  const unit = billUnitOf(it);
  if(mode !== "UNIT" && it.pieces === 1) return "1 pc";
  const q = Pricing.formatQty(it.qty, mode).replace(" "+unit, "");
  return q + (mode !== "UNIT" && it.pieces ? `<span class="c-pieces">(${it.pieces} pc)</span>` : "");
}

/** Plain grouped figure, no symbol — the bill's own columns are already
 *  headed in rupees and a symbol per cell only crowds the grid. */
function fmtMoney(v){
  return (Number(v)||0).toLocaleString("en-IN", {minimumFractionDigits:2, maximumFractionDigits:2});
}

/* ============================================================
   THE PRINTED BILL  (the layout this shop uses)

   Restored verbatim from commit 40907e8 at the shop's request — the
   bill-book redesign that replaced it was not wanted. The plainer
   arrangement is what they print: centred shop header, buyer and
   document boxes side by side, the item grid, then amount-in-words
   beside the totals box, and the terms paragraph at the foot.

   fitBillToPage is deliberately NOT called here. This layout fills the
   sheet through the table's own flex-grow against the page min-height
   set by applyPageSizeStyle, which is how it always worked and why it
   printed on one page.
   ============================================================ */
/* ============================================================
   TEMPLATE-DRIVEN BILL COLUMNS

   The bill used to hard-code its seven columns. These helpers let the
   Print Designer decide which columns appear, in what order, how wide,
   how aligned and under what heading — while every cell still renders
   through the SAME logic the hard-coded bill used, so a default template
   reproduces the shop's existing paper exactly.
   ============================================================ */

/** The active template's config for a document type, or the registry
 *  default when none has loaded yet. Never throws: printing a bill must
 *  not depend on the Print Manager having been opened. */
/**
 * Fetches the default template for both bill types.
 *
 * Failure is deliberately silent: if the request fails the bill still
 * prints, from the built-in fallback columns. A print is not something to
 * block on a settings lookup.
 */
async function loadBillTemplates(){
  state.billTemplates = state.billTemplates || {};
  for(const key of ["sales_invoice", "delivery_challan"]){
    try{
      const list = await api("GET", `/print-manager/templates/${key}`);
      const chosen = (list || []).find(t => t.is_default) || (list || [])[0];
      if(chosen){
        state.billTemplates[key] = {
          ...chosen,
          config: typeof chosen.config === "string" ? JSON.parse(chosen.config) : chosen.config
        };
      }
    }catch(e){ /* fallback columns cover this */ }
  }
}

function billConfig(challan){
  const key = challan ? "delivery_challan" : "sales_invoice";
  const t = (state.billTemplates || {})[key];
  return (t && t.config) || null;
}

/** Columns to print: only those switched on, in the template's order.
 *  Falls back to the classic seven so an unconfigured shop still prints. */
function billColumns(challan){
  const cfg = billConfig(challan);
  if(cfg && Array.isArray(cfg.columns)){
    const on = cfg.columns.filter(c => c && c.show);
    if(on.length) return on;
  }
  return [
    { key:"sn",     label:"Sr No.", width:0, align:"center" },
    { key:"name",   label: challan ? "Product / Item" : "Product Description", width:0, align:"left" },
    { key:"size",   label: challan ? "Description" : "Size", width:0, align:"left" },
    { key:"unit",   label:"Unit",   width:0, align:"left" },
    { key:"qty",    label:"Qty",    width:0, align:"right" },
    { key:"rate",   label:"Rate",   width:0, align:"right" },
    { key:"amount", label:"Amount", width:0, align:"right" }
  ];
}

/* The classes the stylesheet already targets, kept per column key so the
   themes and the print CSS keep working untouched. */
/* Qty, Rate and Amount keep c-num for their alignment AND carry a column
   class of their own, so the stylesheet can hold their width. Without one
   they were all just c-num, the browser sized every column from its
   contents, and a long product name on one line moved the money columns
   for the whole table — so the same challan printed twice put its figures
   in two different places. Added alongside, never instead of: c-num still
   carries the right-align and the nowrap. */
const BILL_CELL_CLASS = {
  sn:"c-sn", size:"c-size", unit:"c-unit",
  qty:"c-num c-qty", rate:"c-num c-rate",
  amount:"c-num c-amt", disc:"c-num c-disc", taxable:"c-num c-taxable",
  gstPct:"c-num c-gstpct",
  cgst:"c-num c-tax", sgst:"c-num c-tax", igst:"c-num c-tax"
};

/**
 * One cell of one line.
 *
 * `showRate` blanks the money cells rather than hiding them — the challan
 * rule the bill has always followed, so staff can write figures in by hand
 * on a "Without Rate" print. A blank, never a misleading 0.00.
 */
function billCellFor(key, it, i, ctx){
  const money = v => ctx.showRate ? fmtPaise(v) : "";
  const gross = (Number(it.qty) || 0) * (Number(it.rate) || 0);
  const discPct = Number(it.discount_pct) || 0;
  const net = gross * (1 - discPct / 100);
  const gstPct = Number(it.gst_rate) || 0;
  const tax = ctx.gstEnabled ? net * (gstPct / 100) : 0;
  const product = (state.products || []).find(p => p.id === it.product_id);

  switch(key){
    case "sn":   return String(i + 1);
    case "name": return escapeHtml(it.name);
    case "size": return escapeHtml(it.size_label || "—");
    case "unit": return escapeHtml(ctx.unitOf(it));
    case "qty":  return ctx.qtyCellOf(it);
    // Rate prints bare, the way the bill always has — the currency symbol
    // sits in the Amount column and the totals box, not on every line.
    case "rate":    return ctx.showRate ? fmtPaise(it.rate).replace("Rs. ", "") : "";
    case "amount":  return money(ctx.lineAmount(it));
    case "disc":    return ctx.showRate && discPct ? discPct.toFixed(2) : "";
    case "taxable": return money(net);
    case "gstPct":  return ctx.gstEnabled ? gstPct + "%" : "";
    case "cgst":    return ctx.gstEnabled && !ctx.isIGST ? money(tax / 2) : "";
    case "sgst":    return ctx.gstEnabled && !ctx.isIGST ? money(tax / 2) : "";
    case "igst":    return ctx.gstEnabled && ctx.isIGST ? money(tax) : "";
    /* The line's own code wins — a bill must keep printing what it was
       actually billed under, even if the product is reclassified later.
       But a BLANK line preserves no history, so it falls back to the
       product's current code. Without this, setting an HSN on a product
       would leave every existing invoice still printing an empty column,
       which reads as the feature being broken. */
    case "hsn":     return escapeHtml(it.hsn_code || (product && product.hsn_code) || "");
    case "code":    return escapeHtml(it.code || (product && product.code) || "");
    case "brand":   return escapeHtml(it.brand || (product && product.brand) || "");
    // Category is not stored on the line, so it comes from the product it
    // was billed from; a deleted product simply prints blank.
    case "category":return escapeHtml((product && product.category) || "");
    case "remarks": return "";
    default:        return "";
  }
}

/** A column's <th>, carrying the designer's width and alignment. */
function billHeadCell(col){
  const cls = BILL_CELL_CLASS[col.key] || "";
  const style = [
    col.width ? "width:" + col.width + "px;" : "",
    col.align ? "text-align:" + col.align + ";" : ""
  ].join("");
  return `<th${cls ? ` class="${cls}"` : ""}${style ? ` style="${style}"` : ""}>${escapeHtml(col.label || "")}</th>`;
}

/** A column's <td>. Alignment is repeated on the body cell because the
 *  stylesheet aligns by class, and a designer override has to beat it. */
function billBodyCell(col, html){
  const cls = BILL_CELL_CLASS[col.key] || "";
  const style = col.align ? ` style="text-align:${col.align};"` : "";
  return `<td${cls ? ` class="${cls}"` : ""}${style}>${html}</td>`;
}

/* ============================================================
   TALLY-STYLE TAX INVOICE

   A different LAYOUT, not a different colour scheme. The existing themes are
   additive CSS over one markup; this needs its own structure — the ruled
   grid of party boxes against dispatch details, the HSN/SAC tax summary, the
   declaration and bank block — so it renders separately and is chosen by the
   same theme setting.

   The classic layout is untouched. Switching the theme back returns the bill
   the shop already approved, byte for byte.

   Columns still come from billColumns(), so anything switched on in the
   Print Designer appears here too rather than this being a second place to
   configure the same thing.
   ============================================================ */

/** Tally prints a rupee figure plain — no symbol in the grid, two decimals. */
function tallyMoney(v){
  const n = Number(v) || 0;
  return n.toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

/**
 * The HSN/SAC summary — the part that makes a bill read as a Tally GST
 * invoice. Lines are grouped by HSN, because that is what the return needs;
 * two products sharing an HSN are one row here even though they are two
 * rows above.
 */
function tallyHsnSummary(inv, items, ctx){
  const groups = new Map();
  for(const it of items){
    const prod = (state.products || []).find(p => p.id === it.product_id);
    const hsn = String(it.hsn_code || (prod && prod.hsn_code) || "").trim() || "—";
    const gross = (Number(it.qty) || 0) * (Number(it.rate) || 0);
    const net = gross * (1 - (Number(it.discount_pct) || 0) / 100);
    const pct = Number(it.gst_rate) || 0;
    const g = groups.get(hsn) || { hsn, taxable: 0, pct, tax: 0 };
    g.taxable += net;
    // A mixed-rate HSN keeps the highest rate seen, and the tax is summed
    // per line rather than recomputed off the group, so the total stays true.
    g.pct = Math.max(g.pct, pct);
    g.tax += ctx.gstEnabled ? net * (pct / 100) : 0;
    groups.set(hsn, g);
  }
  const rows = [...groups.values()];
  if(!rows.length) return "";

  const totals = rows.reduce((a, r) => ({ taxable: a.taxable + r.taxable, tax: a.tax + r.tax }),
                             { taxable: 0, tax: 0 });
  const half = ctx.isIGST ? null : 2;

  const body = rows.map(r => {
    const halfPct = (r.pct / 2).toFixed(2).replace(/\.00$/, "") + "%";
    return `<tr>
      <td>${escapeHtml(r.hsn)}</td>
      <td class="c-num">${tallyMoney(r.taxable)}</td>
      ${ctx.isIGST
        ? `<td class="c-num">${r.pct}%</td><td class="c-num">${tallyMoney(r.tax)}</td>`
        : `<td class="c-num">${halfPct}</td><td class="c-num">${tallyMoney(r.tax / half)}</td>
           <td class="c-num">${halfPct}</td><td class="c-num">${tallyMoney(r.tax / half)}</td>`}
      <td class="c-num">${tallyMoney(r.tax)}</td>
    </tr>`;
  }).join("");

  return `
    <table class="tly-hsn">
      <thead>
        <tr>
          <th rowspan="2">HSN/SAC</th>
          <th rowspan="2" class="c-num">Taxable<br>Value</th>
          ${ctx.isIGST
            ? `<th colspan="2">Integrated Tax</th>`
            : `<th colspan="2">Central Tax</th><th colspan="2">State Tax</th>`}
          <th rowspan="2" class="c-num">Total<br>Tax Amount</th>
        </tr>
        <tr>
          <th class="c-num">Rate</th><th class="c-num">Amount</th>
          ${ctx.isIGST ? "" : `<th class="c-num">Rate</th><th class="c-num">Amount</th>`}
        </tr>
      </thead>
      <tbody>${body}</tbody>
      <tfoot>
        <tr>
          <td><b>Total</b></td>
          <td class="c-num"><b>${tallyMoney(totals.taxable)}</b></td>
          ${ctx.isIGST
            ? `<td></td><td class="c-num"><b>${tallyMoney(totals.tax)}</b></td>`
            : `<td></td><td class="c-num"><b>${tallyMoney(totals.tax / 2)}</b></td>
               <td></td><td class="c-num"><b>${tallyMoney(totals.tax / 2)}</b></td>`}
          <td class="c-num"><b>${tallyMoney(totals.tax)}</b></td>
        </tr>
      </tfoot>
    </table>
    <div class="tly-taxwords">Tax Amount (in words): <b>${Pricing.amountInWords(totals.tax)}</b></div>`;
}

/**
 * The whole page. Returns the inner HTML for .invoice-page, so paper sizing,
 * the one-page fit and the PDF path all keep working unchanged.
 */
function renderTallyInvoiceHtml(inv, cust, cols, rowsHtml, ctx){
  const s = state.settings || {};
  const challan = inv.doc_type === "challan";
  const gstEnabled = !challan && inv.gst_enabled !== 0;
  const isIGST = gstEnabled && inv.tax_type === "IGST";

  const kv = (label, value) => `<div class="tly-kv"><span>${escapeHtml(label)}</span><b>${value || "&nbsp;"}</b></div>`;
  const bank = [
    s.bank_name ? "Bank: " + s.bank_name : "",
    s.bank_account_no ? "A/c No: " + s.bank_account_no : "",
    s.bank_ifsc ? "IFSC: " + s.bank_ifsc : "",
    s.bank_branch ? "Branch: " + s.bank_branch : ""
  ].filter(Boolean);

  /* A consignee address is one that was entered as one. Falling back to
     the buyer's address printed the block above a second time under a
     label that claimed it was somewhere else. Same fix as the classic
     layout below; the two must not disagree about what an address is. */
  const shipTo = String(inv.delivery_address || "").trim();
  const shipNorm = s => String(s || "").toLowerCase().replace(/[^a-z0-9]+/g, "");
  const shipSameAsBuyer = !!shipTo && !!(cust && cust.address)
    && shipNorm(shipTo) === shipNorm(cust.address);
  /* Same rule as the classic layout: the consignee address stays on screen for
     the office and off the paper unless "Print delivery address" is ticked. */
  const printShipTo = billPrefs().printDeliveryAddress === true;
  const eway = inv.eway_bill_no
    ? kv("E-Way Bill No.", escapeHtml(inv.eway_bill_no) +
        (inv.eway_valid_until ? ` <span style="font-weight:400;">(valid to ${escapeHtml(fyDay(inv.eway_valid_until))})</span>` : ""))
    : "";

  return `
    <div class="tly-title">${escapeHtml(challan ? "DELIVERY CHALLAN" : "TAX INVOICE")}</div>

    <div class="tly-grid">
      <div class="tly-left">
        <div class="tly-seller">
          <div class="tly-co">${escapeHtml(s.business_name || "")}</div>
          ${s.address ? `<div>${escapeHtml(s.address)}</div>` : ""}
          ${s.gstin ? `<div>GSTIN/UIN: ${escapeHtml(s.gstin)}</div>` : ""}
          ${s.state ? `<div>State Name: ${escapeHtml(s.state)}</div>` : ""}
          ${s.email ? `<div>E-Mail: ${escapeHtml(s.email)}</div>` : ""}
        </div>
        <div class="tly-party">
          <div class="tly-lbl">Buyer (Bill to)</div>
          <div class="tly-co">${cust ? escapeHtml(cust.name) : "Walk-in Customer"}</div>
          ${cust && cust.address ? `<div>${escapeHtml(cust.address)}</div>` : ""}
          ${cust && cust.gst ? `<div>GSTIN/UIN: ${escapeHtml(cust.gst)}</div>` : ""}
          ${cust && cust.state ? `<div>State Name: ${escapeHtml(cust.state)}</div>` : ""}
          ${cust && cust.phone ? `<div>Mobile: ${escapeHtml(cust.phone)}</div>` : ""}
        </div>
        ${shipTo ? `<div class="tly-party${(printShipTo && !shipSameAsBuyer) ? "" : " screen-only"}">
          <div class="tly-lbl">Consignee (Ship to)</div>
          <div>${escapeHtml(shipTo)}</div>
        </div>` : ""}
      </div>

      <div class="tly-right">
        ${kv("Invoice No.", escapeHtml(inv.challan_no || ""))}
        ${kv("Dated", escapeHtml(fyDay(inv.date)))}
        ${kv("Mode/Terms of Payment", escapeHtml(inv.payment_method || ""))}
        ${kv("Despatched through", escapeHtml(inv.transport_mode || inv.transporter_name || ""))}
        ${kv("Vehicle No.", escapeHtml(inv.vehicle_number || ""))}
        ${kv("Destination", escapeHtml((cust && cust.city) || (cust && cust.state) || ""))}
        ${inv.lr_number ? kv("L.R. No.", escapeHtml(inv.lr_number)) : ""}
        ${eway}
        ${kv("Terms of Delivery", escapeHtml(inv.remarks || ""))}
      </div>
    </div>

    <div class="erp-table-wrap">
      <table class="erp-table tly-items">
        <thead><tr>${cols.map(billHeadCell).join("")}</tr></thead>
        <tbody>${rowsHtml}</tbody>
      </table>
    </div>

    <div class="tly-amtwords">
      <span>Amount Chargeable (in words)</span>
      <b>${ctx.showRate ? Pricing.amountInWords(ctx.displayTotal) : "&nbsp;"}</b>
      <span class="tly-eoe">E. &amp; O.E</span>
    </div>

    ${gstEnabled ? tallyHsnSummary(inv, inv.items || [], { gstEnabled, isIGST }) : ""}

    <div class="tly-foot">
      <div class="tly-foot-l">
        <div class="tly-lbl">Declaration</div>
        <div>We declare that this invoice shows the actual price of the goods
             described and that all particulars are true and correct.</div>
        ${bank.length ? `<div class="tly-bank"><b>Company's Bank Details</b><br>${bank.map(escapeHtml).join("<br>")}</div>` : ""}
      </div>
      <div class="tly-foot-r">
        <div>for <b>${escapeHtml(s.business_name || "")}</b></div>
        <div class="tly-sign">Authorised Signatory</div>
      </div>
    </div>
    <div class="tly-computer">This is a Computer Generated Invoice</div>`;
}

function renderInvoicePageContent(){
  const inv = lastPreviewInvoice; if(!inv) return;
  const cfg = state.settings;
  const cust = state.customers.find(c=>c.id===inv.customer_id);
  const isA4 = state.paperSize==="A4";
  const challan = inv.doc_type === "challan";
  const pageEl = document.getElementById("invoice-page-content");
  pageEl.classList.toggle("size-a5", !isA4);
  applyPrintTheme(pageEl, challan);

  /* Page-level settings from the template. Each is applied only when the
     template actually carries a value, so a shop that has never opened the
     Designer keeps the stylesheet's own metrics exactly as before. */
  {
    const c = billConfig(challan);
    pageEl.style.fontSize = c && c.fontSize ? c.fontSize + "pt" : "";
    pageEl.style.padding  = c && c.margins && c.margins.top ? c.margins.top + "mm" : "";
    // Row height is a floor, not a fixed height: a long product name must
    // still be free to wrap onto a second line rather than be clipped.
    pageEl.style.setProperty("--bill-row-h", c && c.rowHeight ? c.rowHeight + "mm" : "");
    pageEl.classList.toggle("no-rules", !!(c && c.showBorders === false));
  }

  // Previous / Next stepper — outside .invoice-page so it is never captured
  // by the PDF or the printer, which only take the page itself.
  const navEl = document.getElementById("invoice-bill-nav");
  if(navEl){
    navEl.innerHTML = inv.id ? billNavHtml("invoice", inv.id) : "";
    if(inv.id) wireBillNav(navEl, "invoice", inv.id, openExistingInvoice);
  }

  // A challan's item table and totals box keep EXACTLY the same layout
  // whether "Show Rate" is on or off — only the Rate/Amount cell CONTENTS
  // (and the money values in the totals box below) go blank, never hidden
  // columns and never a "0.00", so staff can write the real figures in by
  // hand after printing. "Delivery Challan (With Rate)" vs "(Without Rate)"
  // is a PRINT-TIME choice on the same saved document — the item rate is
  // stored either way (see server/routes/invoices.js), this toggle only
  // controls whether it's PRINTED.
  const showRate = !challan || state.challanShowRate;
  // Which columns, in what order, headed how, how wide and how aligned all
  // come from the active template now. A default template reproduces the
  // classic seven exactly; billColumns() falls back to them outright if no
  // template has loaded, so printing never depends on the Print Manager.
  const cols = billColumns(challan);
  const head = cols.map(billHeadCell).join("");
  const rows = inv.items.map((it,i)=>{
    const mode = it.mode || "UNIT";
    const unit = it.unit_label || (Pricing.MODES[mode] && Pricing.MODES[mode].unit) || "";
    // Area/length modes bill in a different unit than the physical piece
    // count (e.g. 4 sheets at 8x4ft = 32 Sq.ft) — show both so "32" doesn't
    // read as a mismatch against "4". A single piece is shown as just
    // "1 pc" instead, since the billed number adds nothing when there's
    // only one piece. UNIT mode has no such split (qty already IS the
    // piece count), so nothing extra.
    const qtyCell = mode !== "UNIT" && it.pieces === 1
      ? "1 pc"
      : `${Pricing.formatQty(it.qty, mode).replace(" "+unit,"")}${mode !== "UNIT" && it.pieces ? `<div class="c-pieces">(${it.pieces} pc)</div>` : ""}`;
    // The per-line context every cell renderer needs. qtyCellOf and unitOf
    // are passed in rather than duplicated so the piece-count split above
    // stays the single source of that logic.
    const cellCtx = {
      showRate, gstEnabled: !challan && inv.gst_enabled !== 0,
      isIGST: inv.tax_type === "IGST",
      unitOf: () => unit,
      qtyCellOf: () => qtyCell,
      lineAmount: x => (Number(x.qty)||0) * (Number(x.rate)||0) * (1 - (Number(x.discount_pct)||0)/100)
    };
    return `<tr>${cols.map(c => billBodyCell(c, billCellFor(c.key, it, i, cellCtx))).join("")}</tr>`;
  }).join("");
  // Total Quantity is the physical piece count across all items, not the
  // billed area/length sum — matching what gets counted at load/unload,
  // and staying meaningful even when items mix billing units (Sq.ft +
  // Rft + Unit can't be summed together, but pieces always can).
  const totalQtyForFoot = round2(inv.items.reduce((s,it)=>s+(Number(it.pieces)||0),0));
  // Spans computed from the live column list. The old hard-coded
  // colspan 4 / 1 / 3 totalled eight across a seven-column table, and
  // broke outright the moment a column was switched on or off.
  const qtyIdx = cols.findIndex(c => c.key === "qty");
  const tfoot = qtyIdx === -1
    ? `<tfoot><tr><td colspan="${cols.length}" style="text-align:right;">Total Quantity ${totalQtyForFoot}</td></tr></tfoot>`
    : `<tfoot><tr>
    ${qtyIdx > 0 ? `<td colspan="${qtyIdx}" style="text-align:right;">Total Quantity</td>` : ""}
    <td class="c-num">${totalQtyForFoot}</td>
    ${cols.length - qtyIdx - 1 > 0 ? `<td colspan="${cols.length - qtyIdx - 1}"></td>` : ""}
  </tr></tfoot>`;

  // Priced invoice: full totals. Challan: same boxed layout for visual
  // consistency with the shop's paper form, but CGST/SGST/IGST stay at zero
  // here — a challan never carries real GST regardless of what the box
  // shows, and this "Grand Total" is a print-only figure (goods value +
  // transport/loading) that is NEVER what's stored as the invoice's actual
  // total or added to the customer's due — that stays transport+loading only,
  // set server-side, so a challan can never function as a demand for payment.
  const challanSubtotal = inv.items.reduce((s,it)=>s+(it.qty*it.rate||0),0);
  const displayTotal = challan ? (challanSubtotal + inv.transport + inv.loading) : inv.total;
  const discountAmt = challan ? 0 : (inv.discount_amount || 0);
  // A challan never carries real GST, and "Non-GST Invoice" (gst_enabled=0)
  // deliberately has none either — both skip the tax rows entirely.
  const gstEnabled = !challan && inv.gst_enabled !== 0;
  const cgst = gstEnabled ? (inv.cgst || 0) : 0, sgst = gstEnabled ? (inv.sgst || 0) : 0, igst = gstEnabled ? (inv.igst || 0) : 0;
  const isIGST = gstEnabled && inv.tax_type === "IGST";
  // Effective rate shown next to the CGST/SGST/IGST label — derived from the
  // actual stored tax and taxable value (works for a mixed-rate bill too,
  // since it's a weighted average, not any single item's GST%), not hardcoded.
  const taxableGoods = Math.max(0, (inv.subtotal||0) - (inv.discount_amount||0));
  const effectiveRatePct = taxableGoods > 0 ? Math.round(((cgst+sgst+igst) / taxableGoods) * 100) : 0;
  const halfRatePct = Math.round(effectiveRatePct / 2);

  // The totals box keeps the SAME layout regardless of showRate — only the
  // money values that depend on item pricing (Subtotal, Discount, Grand
  // Total) go blank instead of printing a misleading "0.00" when the rate
  // itself isn't shown. Transport/Additional Charges are real entered
  // rupee amounts independent of any item rate, so they still print.
  //
  // Transport is rendered only when there IS one, matching how Additional
  // Charges already behaves: a "Without Rate" challan is meant to come out
  // with every money box empty for staff to fill in by hand, and a printed
  // "Transport ₹0.00" was the one figure still landing on the page. Hiding
  // the row at zero (rather than blanking its value) keeps both print modes
  // identical to each other, since it's absent from both.
  const totalsBox = `<div class="erp-totals-box">
    <div class="erp-tb-row"><span>Subtotal</span><span>${showRate ? fmtPaise(challan?challanSubtotal:inv.subtotal) : ""}</span></div>
    <div class="erp-tb-row"><span>Discount</span><span>${showRate ? (discountAmt>0?"-":"")+fmtPaise(discountAmt) : ""}</span></div>
    ${inv.transport ? `<div class="erp-tb-row"><span>Transport</span><span>${fmtPaise(inv.transport)}</span></div>` : ""}
    ${inv.loading ? `<div class="erp-tb-row"><span>Additional Charges</span><span>${fmtPaise(inv.loading)}</span></div>` : ""}
    ${!gstEnabled ? "" : isIGST
      ? `<div class="erp-tb-row"><span>IGST ${effectiveRatePct}%</span><span>${fmtPaise(igst)}</span></div>`
      : `<div class="erp-tb-row"><span>CGST ${halfRatePct}%</span><span>${fmtPaise(cgst)}</span></div><div class="erp-tb-row"><span>SGST ${halfRatePct}%</span><span>${fmtPaise(sgst)}</span></div>`}
    ${!challan && inv.round_off ? `<div class="erp-tb-row"><span>Round Off</span><span>${inv.round_off>0?"+":""}${fmtPaise(inv.round_off)}</span></div>` : ""}
    <div class="erp-tb-row erp-tb-grand"><span>Grand Total</span><span>${showRate ? fmtPaise(displayTotal) : ""}</span></div>
    ${!challan && inv.advance>0 ? `<div class="erp-tb-row"><span>Advance Paid</span><span>-${fmtPaise(inv.advance)}</span></div>
    <div class="erp-tb-row" style="font-weight:800;"><span>Balance Due</span><span>${fmtPaise(inv.balance_due)}</span></div>` : ""}
  </div>`;

  /* A DELIVERY address is one that was actually entered as one.

     This used to fall back to the customer's own address, which is the
     address the Deliver To box above already prints — so a challan with
     no separate delivery address printed the same lines twice, once
     under Deliver To and once under Delivery Address. The fallback was
     the whole of that bug.

     Falling back also made the label a lie: "Delivery Address" on a
     line that is simply the customer's registered address tells the
     reader something that was never entered. */
  const deliveryAddr = String(inv.delivery_address || "").trim();

  /* And even when one WAS entered, it is only worth a second block if it
     says something the Deliver To box does not. Compared loosely, because
     the same address typed twice differs by a comma and a capital. */
  const norm = s => String(s || "").toLowerCase().replace(/[^a-z0-9]+/g, "");
  const addrAlreadyShown = !!deliveryAddr && !!(cust && cust.address)
    && norm(deliveryAddr) === norm(cust.address);
  /* Where the goods went is the shop's own record. It stays visible in the
     preview so the office can check it, and is kept off the paper unless
     "Print Delivery Address" is ticked in Bill Print Settings. */
  const printAddr = billPrefs().printDeliveryAddress === true;
  const bottomLeft = `<div class="erp-bottom-left">
    ${/* Ticked -> printed, once. Unticked -> not on paper at all, but still
         on screen, because the office needs to see where the goods went
         whatever the customer's copy shows.

         A delivery address identical to the one already under Deliver To
         is kept off the paper either way: printing it twice is not more
         information, it is the same information taking up the space the
         remarks needed. */""}
    ${deliveryAddr
      ? `<div${(printAddr && !addrAlreadyShown) ? "" : ` class="screen-only"`}><b>Delivery Address:</b> ${escapeHtml(deliveryAddr)}</div>`
      : ""}
    ${inv.remarks ? `<div><b>Remarks:</b> ${escapeHtml(inv.remarks)}</div>` : ""}
    ${/* Status and Acknowledgement are for the shop, not the customer. They
         track what the office still owes itself — raise the tax invoice, chase
         the signed copy — and printing "not yet billed" on the copy handed over
         with the goods invites the wrong question at the door.

         They stay on screen and disappear on paper: .screen-only is hidden by
         the print stylesheet, so the preview shows the full picture and the
         printed challan does not. */""}
    ${challan ? `<div class="screen-only"><b>Status:</b> ${inv.converted_invoice_id ? "Billed (Tax Invoice raised)" : "Pending — not yet billed"}</div>` : ""}
    ${challan ? `<div class="screen-only"><b>Acknowledgement:</b> ${inv.ack_status === "Received"
      ? "Received" + (inv.ack_receiver_name ? " — signed by " + escapeHtml(inv.ack_receiver_name) : "")
      : "Pending — signed copy not yet returned"}</div>` : ""}
    ${showRate ? `<div class="erp-words"><b>Amount in Words:</b> ${Pricing.amountInWords(displayTotal)}</div>` : ""}
  </div>`;

  // The heading the template names, or the wording the bill has always used.
  const tplCfg = billConfig(challan) || {};
  const bannerText = (tplCfg.title || "").trim() || (challan ? "DELIVERY CHALLAN" : "ESTIMATE CHALLAN");

  /* Tally Format is a different LAYOUT, so it builds its own page from the
     same columns and rows computed above. Every other theme falls through
     to the classic markup below, unchanged. */
  if(printThemeFor(challan) === "tallyfull"){
    document.getElementById("invoice-page-content").innerHTML =
      renderTallyInvoiceHtml(inv, cust, cols, rows, {
        showRate, displayTotal, gstEnabled, isIGST
      });
    return;
  }
  document.getElementById("invoice-page-content").innerHTML = `
    <div class="erp-banner">${bannerText}</div>
    <div class="erp-header">
      <div class="erp-biz-name">${escapeHtml(cfg.business_name)}</div>
      ${cfg.tagline ? `<div class="erp-tag">${escapeHtml(cfg.tagline)}</div>` : ""}
      ${cfg.address ? `<div class="erp-addr">${escapeHtml(cfg.address)}</div>` : ""}
      <div class="erp-contact-line">${[
        cfg.gstin ? `GSTIN: ${escapeHtml(cfg.gstin)}` : "",
        cfg.phones ? `Ph: ${escapeHtml(cfg.phones)}` : "",
        cfg.email ? `Email: ${escapeHtml(cfg.email)}` : "",
        cfg.website ? `Website: ${escapeHtml(cfg.website)}` : ""
      ].filter(Boolean).join("  |  ")}</div>
    </div>

    <div class="erp-parties">
      <div class="erp-party-box">
        <div class="erp-box-label">${challan ? "Deliver To" : "Buyer"}</div>
        <div class="erp-box-name">${cust?escapeHtml(cust.name):"Walk-in Customer"}</div>
        ${cust&&cust.address ? `<div>${escapeHtml(cust.address)}</div>` : ""}
        ${cust&&cust.phone ? `<div>Mobile: ${escapeHtml(cust.phone)}</div>` : ""}
        ${cust&&cust.gst ? `<div>GSTIN: ${escapeHtml(cust.gst)}</div>` : ""}
        ${cust&&cust.state ? `<div>State: ${escapeHtml(cust.state)}</div>` : ""}
      </div>
      <div class="erp-doc-box">
        <div class="erp-kv"><span>${challan ? "Challan No." : "Estimate No."}</span><b>${inv.challan_no}</b></div>
        <div class="erp-kv"><span>Date</span><b>${inv.date}</b></div>
        ${inv.delivery_man ? `<div class="erp-kv"><span>Salesperson</span><b>${escapeHtml(inv.delivery_man)}</b></div>` : ""}
        ${inv.vehicle_number ? `<div class="erp-kv"><span>Vehicle No.</span><b>${escapeHtml(inv.vehicle_number)}</b></div>` : ""}
      </div>
    </div>

    <div class="erp-table-wrap">
      <table class="erp-table">
        <thead><tr>${head}</tr></thead>
        <tbody>${rows}</tbody>
        ${tfoot}
      </table>
    </div>

    <div class="erp-bottom">
      ${bottomLeft}
      ${totalsBox}
    </div>

    <div class="erp-terms">${challan
      ? `<strong>PLYWOOD, BLACKBOARD, ARE MANUFACTURED FROM NATURAL WOOD WHICH IS BELOW BIO DEGRADEBLE, WE DONOT GUARANTEE AGAINST ANY NATURAL DECAY DEFICIENTY, DETORATION AND LIKE INCLUDING MANUFACTURING DEFACT AND/OR IMPERFACT QUALITY</strong>`
      : `<strong>NO GURANTEE AND WARRANTY FOR DECORATIVE PRODUCTS AND AIR BUBBLES IN LAMMINATES, ACRYLIC AND PVC LAMINATES OR ANY SHADE VARIATION AFTER INSTALLATION. NO EXCHANGE. NO RETURN IN ANY CONDITION. PLEASE CHECK THE MATERIAL ON DELIVERY.</strong>`}</div>
  `;
}

/* ============================================================
   THE BILL-BOOK LAYOUT  (kept, not currently used)

   Built to the mockup: logo header, boxed title, ORIGINAL marking,
   ruled filler rows, three-box footer with bank details, navy grand
   total. Replaced as the default because the shop preferred the older,
   plainer layout below.

   Kept whole rather than removed so nothing is lost: to bring it back,
   point renderInvoicePageContent at it.
   ============================================================ */
function renderBillBookLayout(){
  const inv = lastPreviewInvoice; if(!inv) return;
  const cfg = state.settings || {};
  const cust = state.customers.find(c=>c.id===inv.customer_id);
  const challan = inv.doc_type === "challan";
  const prefs = billPrefs();
  /* state.paperSize is the single source of truth for paper, because
     applyPageSizeStyle() — which sets @page and the full-sheet min-height —
     reads it. Reading prefs.paper here instead meant the two disagreed: with
     no saved preference, prefs.paper defaulted to A4 while state.paperSize
     defaulted to A5, so the sheet was sized A5 and the bill was drawn A4.
     271mm of content onto a 190mm sheet is a two-page bill. The saved
     preference now SEEDS state.paperSize when a preview opens (see
     openInvoicePreview) rather than competing with it. */
  const isA4 = state.paperSize === "A4";

  const pageEl = document.getElementById("invoice-page-content");
  pageEl.classList.toggle("size-a5", !isA4);
  applyPrintTheme(pageEl, challan);

  const navEl = document.getElementById("invoice-bill-nav");
  if(navEl){
    navEl.innerHTML = inv.id ? billNavHtml("invoice", inv.id) : "";
    if(inv.id) wireBillNav(navEl, "invoice", inv.id, openExistingInvoice);
  }

  /* A challan can print with the rate column blank so staff write the figures
     in by hand — the layout stays byte-for-byte identical either way, so the
     ruled boxes still line up. An invoice can now do the same. */
  const showRate = challan ? state.challanShowRate : prefs.showRate !== false;

  /* A challan never carries GST, and a Non-GST Invoice deliberately has none.
     Both come from the SAVED document — the print panel shows this but cannot
     change it, because the tax on the paper must match the tax in the books. */
  const gstEnabled = !challan && inv.gst_enabled !== 0;
  const isIGST = gstEnabled && inv.tax_type === "IGST";
  const ctx = { prefs, showRate, gstEnabled, isIGST };

  const cols = billColumns(ctx);
  const items = inv.items || [];

  const headRow = cols.map(c=>`<th class="${c.cls}">${escapeHtml(c.label)}</th>`).join("");
  const bodyRows = items.map((it,i)=>
    `<tr>${cols.map(c=>`<td class="${c.cls}">${c.cell(it,i)}</td>`).join("")}</tr>`).join("");

  /* No filler rows are written here. They are added AFTER the page exists,
     by fitBillToPage(), which measures how much room is actually left and
     adds exactly that many.

     A fixed count cannot work: the page already carries a full-sheet
     min-height, and adding a set twelve rows on top of the header, totals
     and the three footer boxes pushed a two-item bill onto a second sheet.
     How many rows fit depends on how many columns are on, how long the
     terms are, whether the bank box is filled in — none of which a constant
     can know. */
  const filler = "";

  /* Totals. A challan's are print-only: the goods value plus any transport,
     never stored as what the customer owes (that stays transport + loading,
     set server-side), so a challan can never act as a demand for payment. */
  const challanSubtotal = round2(items.reduce((s,it)=>s+billLineNet(it), 0));
  const subtotal = challan ? challanSubtotal : inv.subtotal;
  const discountAmt = challan ? 0 : (inv.discount_amount || 0);
  const displayTotal = challan ? round2(challanSubtotal + inv.transport + inv.loading) : inv.total;
  const cgst = gstEnabled ? (inv.cgst||0) : 0;
  const sgst = gstEnabled ? (inv.sgst||0) : 0;
  const igst = gstEnabled ? (inv.igst||0) : 0;
  const taxableGoods = round2(Math.max(0, subtotal - discountAmt));
  const effRate = taxableGoods > 0 ? Math.round(((cgst+sgst+igst)/taxableGoods)*100) : 0;
  const halfRate = Math.round(effRate/2);

  const tRow = (label, value, cls) =>
    `<div class="bt-row${cls?" "+cls:""}"><span>${label}</span><span>${value}</span></div>`;
  const money = v => showRate ? fmtMoney(v) : "";

  const totalsBox = `<div class="bill-totals">
    ${tRow("Sub Total", money(subtotal))}
    ${tRow("Discount", showRate ? (discountAmt>0?"-":"")+fmtMoney(discountAmt) : "")}
    ${gstEnabled ? tRow("Taxable Amount", money(taxableGoods)) : ""}
    ${prefs.cols.transport && inv.transport ? tRow("Transport Charges", fmtMoney(inv.transport)) : ""}
    ${prefs.cols.labour && inv.loading ? tRow("Labour Charges", fmtMoney(inv.loading)) : ""}
    ${!gstEnabled ? "" : isIGST
      ? tRow(`IGST @ ${effRate}%`, money(igst))
      : tRow(`CGST @ ${halfRate}%`, money(cgst)) + tRow(`SGST @ ${halfRate}%`, money(sgst))}
    ${!challan && inv.round_off ? tRow("Round Off", (inv.round_off>0?"+":"")+fmtMoney(inv.round_off)) : ""}
    ${tRow("Grand Total ₹", money(displayTotal), "bt-grand")}
    ${!challan && inv.advance>0
      ? tRow("Advance Paid", "-"+fmtMoney(inv.advance)) + tRow("Balance Due", fmtMoney(inv.balance_due), "bt-bold")
      : ""}
  </div>`;

  /* The meta strip under the party block: what the bill carries, who sold it,
     how it travelled. Each chip is omitted when there is nothing to say,
     rather than printing an empty label.

     With Rate / Without Rate is deliberately NOT here. It is a choice about
     how this copy is printed, not a fact about the sale, and a customer
     holding the bill has no use for it — on a Without Rate copy it would be
     the one filled-in thing on a page of blanks. The setting stays in the
     print panel, where it belongs. */
  const metaChips = [
    gstEnabled ? `<span class="bm-chip">GST Type : <b>${isIGST ? "IGST" : "CGST + SGST"}</b></span>`
               : `<span class="bm-chip">GST Type : <b>No GST</b></span>`,
    inv.delivery_man ? `<span class="bm-chip">Salesman : <b>${escapeHtml(inv.delivery_man)}</b></span>` : "",
    inv.transport_mode ? `<span class="bm-chip">Transportation : <b>${escapeHtml(inv.transport_mode)}</b></span>` : "",
    inv.vehicle_number ? `<span class="bm-chip">Vehicle : <b>${escapeHtml(inv.vehicle_number)}</b></span>` : ""
  ].filter(Boolean).join("");

  const title = challan
    ? (cfg.challan_title || "DELIVERY CHALLAN")
    : (cfg.invoice_title || "TAX INVOICE");

  const est = inv.estimate;
  const leftInfo = [
    [challan ? "Challan No." : "Bill No.", escapeHtml(inv.challan_no)],
    ["Date", fyDay(inv.date)],
    est ? ["Estimate No.", escapeHtml(est.quotation_no)] : null,
    est ? ["Estimate Date", fyDay(est.date)] : null
  ].filter(Boolean);
  const rightInfo = [
    ["Party Name", cust ? escapeHtml(cust.name) : "Walk-in Customer"],
    cust && cust.phone ? ["Mobile", escapeHtml(cust.phone)] : null,
    cust && cust.address ? ["Address", escapeHtml(cust.address)] : null,
    cust && cust.gst ? ["GSTIN", escapeHtml(cust.gst)] : null
  ].filter(Boolean);
  const kvHtml = rows => rows.map(([k,v])=>
    `<div class="bi-row"><span class="bi-k">${k}</span><span class="bi-c">:</span><span class="bi-v">${v}</span></div>`).join("");

  const hasBank = cfg.bank_name || cfg.bank_account_no || cfg.bank_ifsc;
  const dueDateLine = inv.due_date ? `<div class="bf-row"><span>Due Date</span><span>: ${fyDay(inv.due_date)}</span></div>` : "";

  pageEl.innerHTML = `
    <div class="bill-head">
      ${cfg.logo_data ? `<div class="bh-logo"><img src="${cfg.logo_data}" alt=""></div>` : `<div class="bh-logo bh-logo-empty"></div>`}
      <div class="bh-mid">
        <div class="bh-name">${escapeHtml(cfg.business_name || "")}</div>
        ${cfg.tagline ? `<div class="bh-tag">${escapeHtml(cfg.tagline)}</div>` : ""}
        ${cfg.address ? `<div class="bh-addr">${escapeHtml(cfg.address)}</div>` : ""}
        <div class="bh-contact">${[
          cfg.phones ? "☎ " + escapeHtml(cfg.phones) : "",
          cfg.email ? "✉ " + escapeHtml(cfg.email) : "",
          cfg.website ? escapeHtml(cfg.website) : ""
        ].filter(Boolean).join("  |  ")}</div>
      </div>
      <div class="bh-right">
        ${cfg.show_copy_label ? `<div class="bh-copy">ORIGINAL</div>` : ""}
        ${cfg.gstin ? `<div class="bh-gstin">GSTIN : ${escapeHtml(cfg.gstin)}</div>` : ""}
      </div>
    </div>

    <div class="bill-title"><span>${escapeHtml(title)}</span></div>

    <div class="bill-info">
      <div class="bi-col">${kvHtml(leftInfo)}</div>
      <div class="bi-col">${kvHtml(rightInfo)}</div>
    </div>

    <div class="bill-meta">${metaChips}</div>

    <div class="bill-items">
      <table>
        <thead><tr>${headRow}</tr></thead>
        <tbody>${bodyRows}${filler}</tbody>
      </table>
    </div>

    <div class="bill-lower">
      <div class="bl-left">
        <div class="bl-words">
          <div class="bl-label">Amount in Words :</div>
          <div class="bl-words-text">${showRate ? escapeHtml(Pricing.amountInWords(displayTotal)) : "&nbsp;"}</div>
        </div>
        ${prefs.cols.remarks ? `<div class="bl-remarks">
          <div class="bl-label">Remarks :</div>
          <div class="bl-remarks-text">${escapeHtml(inv.remarks || "")}</div>
        </div>` : ""}
      </div>
      ${totalsBox}
    </div>

    <div class="bill-foot">
      <div class="bf-box">
        <div class="bf-title">Payment Details :</div>
        ${!challan ? `<div class="bf-row"><span>Payment Type</span><span>: ${escapeHtml(inv.payment_method || "—")}</span></div>` : ""}
        ${dueDateLine}
        ${!challan && showRate ? `<div class="bf-row bf-due"><span>Balance Due</span><span>: ₹ ${fmtMoney(inv.balance_due)}</span></div>` : ""}
        ${challan ? `<div class="bf-row"><span>Status</span><span>: ${inv.converted_invoice_id ? "Billed" : "Pending — not yet billed"}</span></div>` : ""}
      </div>
      ${hasBank ? `<div class="bf-box">
        <div class="bf-title">Bank Details :</div>
        ${cfg.bank_name ? `<div class="bf-line">${escapeHtml(cfg.bank_name)}</div>` : ""}
        ${cfg.bank_account_no ? `<div class="bf-line">A/c No. ${escapeHtml(cfg.bank_account_no)}</div>` : ""}
        ${cfg.bank_ifsc ? `<div class="bf-line">IFSC : ${escapeHtml(cfg.bank_ifsc)}</div>` : ""}
        ${cfg.bank_branch ? `<div class="bf-line">Branch : ${escapeHtml(cfg.bank_branch)}</div>` : ""}
      </div>` : ""}
      <div class="bf-box bf-sign">
        <div class="bf-title bf-sign-for">For ${escapeHtml(cfg.business_name || "")}</div>
        <div class="bf-sign-line">Authorised Signature</div>
      </div>
    </div>

    ${cfg.footer_message ? `<div class="bill-thanks">${escapeHtml(cfg.footer_message)}</div>` : ""}

    <div class="bill-terms">${challan
      ? `PLYWOOD, BLACKBOARD, ARE MANUFACTURED FROM NATURAL WOOD WHICH IS BELOW BIO DEGRADEBLE, WE DONOT GUARANTEE AGAINST ANY NATURAL DECAY DEFICIENTY, DETORATION AND LIKE INCLUDING MANUFACTURING DEFACT AND/OR IMPERFACT QUALITY`
      : `NO GURANTEE AND WARRANTY FOR DECORATIVE PRODUCTS AND AIR BUBBLES IN LAMMINATES, ACRYLIC AND PVC LAMINATES OR ANY SHADE VARIATION AFTER INSTALLATION. NO EXCHANGE. NO RETURN IN ANY CONDITION. PLEASE CHECK THE MATERIAL ON DELIVERY.`}</div>
  `;

  fitBillToPage(cols.length);
}


/**
 * Rules the item table down to the foot of the page — using exactly as many
 * blank rows as actually fit, measured, not guessed.
 *
 * The page carries a full-sheet min-height so a short bill still fills the
 * paper. That means the page is ALWAYS at least a full sheet tall, so the
 * height to measure against is the height of the real content with that
 * minimum lifted — which is what the temporary minHeight:0 below is for.
 *
 * A fixed row count cannot do this job. How much room is left depends on how
 * many columns are switched on, how long the terms run, whether the bank box
 * is filled in and how many items there already are. Twelve rows was right
 * for one of those combinations and pushed the rest onto a second sheet.
 *
 * When the real items already fill or overflow the page, nothing is added:
 * a long bill is allowed to run to a second sheet, which is correct, rather
 * than being squeezed.
 */
function fitBillToPage(colCount){
  const page = document.getElementById("invoice-page-content");
  if(!page) return;
  const tbody = page.querySelector(".bill-items tbody");
  if(!tbody) return;

  tbody.querySelectorAll(".bill-filler").forEach(r => r.remove());

  const blankRow = () => {
    const tr = document.createElement("tr");
    tr.className = "bill-filler";
    tr.innerHTML = Array.from({length: colCount}, ()=>"<td>&nbsp;</td>").join("");
    return tr;
  };

  // Same source as applyPageSizeStyle and the renderer, so all three agree.
  const isA4 = state.paperSize === "A4";
  const pageH = isA4 ? 297 : 210, margin = isA4 ? 6 : 3, safety = 14;
  const MM_TO_PX = 96 / 25.4;
  const targetPx = (pageH - margin * 2 - safety) * MM_TO_PX;

  // Measure the real content, with the full-sheet minimum lifted.
  const savedMin = page.style.minHeight;
  page.style.minHeight = "0";
  const contentPx = page.scrollHeight;

  // One blank row's height, taken from a real row rather than assumed.
  const probe = blankRow();
  tbody.appendChild(probe);
  const rowPx = probe.getBoundingClientRect().height || 15;
  probe.remove();

  const room = targetPx - contentPx;
  page.style.minHeight = savedMin;

  if(room < rowPx) return;   // already full, or genuinely a two-page bill
  const rows = Math.floor(room / rowPx);
  const frag = document.createDocumentFragment();
  for(let i = 0; i < rows; i++) frag.appendChild(blankRow());
  tbody.appendChild(frag);
}

/* ============================================================
   BILL PRINT SETTINGS

   What the panel controls and, just as importantly, what it does not.

   It controls PRESENTATION: paper, which columns appear, whether rates
   print. All of that is saved shop-wide in settings.print_prefs, so the
   format an owner sets once is what every counter prints.

   It does NOT control the figures. GST type and whether a bill carries GST
   are properties of the SAVED BILL — they set the tax charged, the
   customer's balance and the GST return. The panel shows them so the
   operator can see what they are about to print, and offers an Edit Bill
   link, but changing them here would let the paper in a customer's hand
   disagree with the books. That is why they are read-only.
   ============================================================ */

const BILL_PREF_DEFAULTS = {
  paper: "A4",
  showRate: true,
  /* The delivery address is office information, not something the customer
     needs on the sheet handed over with the goods, so it stays on screen and
     off paper unless the shop deliberately turns it on. */
  printDeliveryAddress: false,
  cols: {
    sn: 1, name: 1, size: 1, qty: 1, unit: 1, rate: 1, disc: 1, amount: 1,
    taxable: 0, cgst: 0, sgst: 0, igst: 0,
    transport: 1, labour: 1, remarks: 1
  }
};

/* The checkbox list, in the order the panel shows it. `col` is the key in
   prefs.cols; `hint` explains anything not obvious from the label alone. */
const BILL_PREF_COLUMNS = [
  { col:"sn",       label:"Sr. No." },
  { col:"name",     label:"Item Name" },
  { col:"size",     label:"Size / Description" },
  { col:"qty",      label:"Quantity" },
  { col:"unit",     label:"Unit" },
  { col:"rate",     label:"Rate" },
  { col:"disc",     label:"Discount" },
  { col:"amount",   label:"Amount" },
  { col:"taxable",  label:"Taxable Amount" },
  { col:"cgst",     label:"CGST",  hint:"Only prints on a CGST + SGST bill" },
  { col:"sgst",     label:"SGST",  hint:"Only prints on a CGST + SGST bill" },
  { col:"igst",     label:"IGST",  hint:"Only prints on an IGST bill" },
  { col:"transport",label:"Transport Charges" },
  { col:"labour",   label:"Labour Charges" },
  { col:"remarks",  label:"Remarks" }
];

/** Current preferences, always complete — a stored value missing a key (from
 *  an older save, or a hand-edited row) falls back to the default rather than
 *  reaching the renderer as undefined and hiding a column by accident.
 *
 *  While the panel is open its working copy wins, so ticking a box redraws the
 *  bill straight away. Close the panel without saving and the shop default
 *  comes back — the preview is never showing something nobody chose. */
function billPrefs(){
  if(billPanelPrefs) return billPanelPrefs;
  let stored = {};
  try{ stored = JSON.parse((state.settings && state.settings.print_prefs) || "{}") || {}; }
  catch(e){ stored = {}; }
  return {
    paper: stored.paper === "A5" ? "A5" : "A4",
    showRate: stored.showRate !== false,
    // Off unless explicitly saved on, so an older stored preference that
    // predates this setting keeps the address off the printed sheet.
    printDeliveryAddress: stored.printDeliveryAddress === true,
    cols: { ...BILL_PREF_DEFAULTS.cols, ...(stored.cols || {}) }
  };
}

/** Saves shop-wide. Owner-only server-side, so staff changing the panel see
 *  it apply to the bill in front of them but cannot alter the shop default. */
async function saveBillPrefs(prefs){
  const json = JSON.stringify(prefs);
  if(state.settings) state.settings.print_prefs = json;
  try{
    await api("PUT", "/settings/print-prefs", { printPrefs: json });
    return true;
  }catch(e){
    // Staff can still print with their choices; only the saving is refused.
    toast(e.message || "Could not save as default.");
    return false;
  }
}

/* Working copy while the panel is open. Edits apply to the preview at once;
   "Save as Default" is what makes them stick for everyone. */
let billPanelPrefs = null;

/** The working copy, created on demand.
 *
 *  Every panel control goes through this rather than touching billPanelPrefs
 *  directly. Seeding it only when the panel opens looked fine and was not:
 *  if the panel's state and the variable ever fell out of step, each control
 *  threw on a null and the bill silently stopped responding to the panel —
 *  which is exactly what happened. Creating it on first use means a control
 *  works whenever it is reachable, whatever the panel did before. */
function panelPrefs(){
  if(!billPanelPrefs) billPanelPrefs = JSON.parse(JSON.stringify(billPrefs()));
  return billPanelPrefs;
}

function renderBillPanel(){
  const inv = lastPreviewInvoice;
  const el = document.getElementById("bill-panel-body");
  if(!el || !inv) return;
  const p = billPanelPrefs;
  const challan = inv.doc_type === "challan";
  const gstEnabled = !challan && inv.gst_enabled !== 0;
  const isIGST = gstEnabled && inv.tax_type === "IGST";

  const check = (id, label, checked, hint) => `
    <label class="bp-check">
      <input type="checkbox" data-bp-col="${id}"${checked ? " checked" : ""}>
      <span>${escapeHtml(label)}${hint ? `<span class="bp-hint">${escapeHtml(hint)}</span>` : ""}</span>
    </label>`;

  const radio = (name, value, label, checked, disabled) => `
    <label class="bp-radio${disabled ? " bp-disabled" : ""}">
      <input type="radio" name="${name}" value="${value}"${checked ? " checked" : ""}${disabled ? " disabled" : ""}>
      <span>${escapeHtml(label)}</span>
    </label>`;

  el.innerHTML = `
    <div class="bp-group">
      <div class="bp-label">Select Format</div>
      <div class="bp-row">
        ${radio("bp-paper","A4","A4", p.paper==="A4")}
        ${radio("bp-paper","A5","A5", p.paper==="A5")}
      </div>
    </div>

    <div class="bp-group">
      <div class="bp-label">Show / Hide Columns</div>
      ${BILL_PREF_COLUMNS.map(c=>check(c.col, c.label, !!p.cols[c.col], c.hint)).join("")}
    </div>

    <div class="bp-group">
      <div class="bp-label">Delivery Address</div>
      <label class="bp-check">
        <input type="checkbox" id="bp-delivery-addr"${p.printDeliveryAddress ? " checked" : ""}>
        <span>Print delivery address on the bill</span>
      </label>
      <div class="bp-hint bp-hint-block">Off by default. The address always shows here on
      screen for the office; tick this to include it on the printed sheet as well.</div>
    </div>

    <div class="bp-group">
      <div class="bp-label">Rate Display Option</div>
      ${radio("bp-rate","with","With Rate", p.showRate)}
      ${radio("bp-rate","without","Without Rate", !p.showRate)}
      <div class="bp-hint bp-hint-block">The Rate and Amount columns print blank, with the
      layout unchanged, so figures can be written in by hand.</div>
    </div>

    <div class="bp-group">
      <div class="bp-label">GST Option</div>
      ${radio("bp-gst","cgst","CGST + SGST", gstEnabled && !isIGST, true)}
      ${radio("bp-gst","igst","IGST", isIGST, true)}
      ${radio("bp-gst","none","No GST", !gstEnabled, true)}
      <div class="bp-hint bp-hint-block">This is what the bill itself carries &mdash; it sets the
      tax charged, the customer's balance and your GST return, so it is not a print choice.
      ${inv.id && !challan ? `<a href="#" id="bp-edit-gst">Edit this bill</a> to change it.` : ""}</div>
    </div>

    <div class="bp-group">
      <div class="bp-label">Document Title</div>
      <input type="text" id="bp-title" class="bp-input"
             value="${escapeHtml(challan ? (state.settings.challan_title||"") : (state.settings.invoice_title||""))}"
             placeholder="${challan ? "DELIVERY CHALLAN" : "TAX INVOICE"}">
      <div class="bp-label" style="margin-top:12px;">Footer Message</div>
      <input type="text" id="bp-footer" class="bp-input"
             value="${escapeHtml(state.settings.footer_message||"")}"
             placeholder="Thank you for your business!">
      <div class="bp-hint bp-hint-block">Saved for every bill, not just this one.</div>
    </div>

    <div class="bp-group bp-actions">
      <button class="btn btn-gold" id="bp-save">Save as Default</button>
    </div>
  `;

  el.querySelectorAll("[data-bp-col]").forEach(cb=>{
    cb.addEventListener("change", ()=>{
      panelPrefs().cols[cb.dataset.bpCol] = cb.checked ? 1 : 0;
      renderInvoicePageContent();
    });
  });
  el.querySelectorAll('[name="bp-paper"]').forEach(r=>{
    r.addEventListener("change", ()=>{
      panelPrefs().paper = r.value;
      state.paperSize = r.value;
      renderInvoicePageContent();
    });
  });
  el.querySelectorAll('[name="bp-rate"]').forEach(r=>{
    r.addEventListener("change", ()=>{
      panelPrefs().showRate = r.value === "with";
      if(challan) state.challanShowRate = billPanelPrefs.showRate;
      renderInvoicePageContent();
    });
  });

  const addrBox = document.getElementById("bp-delivery-addr");
  if(addrBox) addrBox.addEventListener("change", ()=>{
    panelPrefs().printDeliveryAddress = addrBox.checked;
    renderInvoicePageContent();
  });

  const editLink = document.getElementById("bp-edit-gst");
  if(editLink) editLink.addEventListener("click", e=>{
    e.preventDefault();
    closeInvoicePreview();
    openExistingInvoice(inv.id);
  });

  document.getElementById("bp-save").addEventListener("click", async ()=>{
    const title = document.getElementById("bp-title").value.trim();
    const footer = document.getElementById("bp-footer").value;
    const body = { footerMessage: footer };
    if(title) body[challan ? "challanTitle" : "invoiceTitle"] = title;
    try{
      const saved = await api("PUT", "/settings", body);
      state.settings = { ...state.settings, ...saved };
    }catch(e){ toast(e.message || "Could not save the wording."); return; }
    const ok = await saveBillPrefs(panelPrefs());
    if(ok) toast("Saved as the default for every bill.", "ok");
    renderInvoicePageContent();
  });
}

function toggleBillPanel(){
  const panel = document.getElementById("bill-panel");
  if(!panel) return;
  const open = panel.classList.toggle("open");
  document.getElementById("bill-panel-btn").classList.toggle("active", open);
  if(open){
    // Fresh from the saved default each time the panel opens, so an
    // abandoned edit never leaks into the next bill.
    billPanelPrefs = null;
    panelPrefs();
    renderBillPanel();
  }else{
    billPanelPrefs = null;
  }
  renderInvoicePageContent();
}
/**
 * Rasterises the on-screen invoice/challan into a jsPDF document and hands
 * back both the pdf object and a sensible filename — shared by the Download
 * button and the Share-as-PDF-on-WhatsApp button below, so there's exactly
 * one place that knows how to turn the preview into a PDF.
 */
async function buildInvoicePdf(){
  if(typeof html2canvas === "undefined" || typeof window.jspdf === "undefined"){
    throw new Error("PDF libraries not loaded");
  }
  const node = document.getElementById("invoice-page-content");
  const { jsPDF } = window.jspdf;
  const isA4 = state.paperSize==="A4";
  const pdf = new jsPDF({unit:"mm", format: isA4 ? "a4" : "a5"});
  const pageWidth = pdf.internal.pageSize.getWidth();
  const pageHeight = pdf.internal.pageSize.getHeight();
  const imgWidth = pageWidth;
  // The printed page itself uses only hex colours (see .invoice-page in
  // style.css), but html2canvas 1.4.1 also walks and resolves styles on
  // ANCESTOR elements (body, the fullscreen wrapper, :root) for layout
  // context, and those still use the app's oklch() theme — which this old
  // html2canvas build cannot parse, so it throws before any image is drawn.
  // `onclone` lets us patch the OFF-SCREEN CLONE that html2canvas rasterises
  // — never the live page the user is looking at — by overriding the theme
  // variables with plain hex equivalents just for that clone.
  const canvas = await html2canvas(node, {
    scale:2, backgroundColor:"#ffffff", useCORS:true,
    onclone: (clonedDoc) => {
      const style = clonedDoc.createElement("style");
      style.textContent = `:root{
        --navy:#1e2a4a; --navy-2:#182140; --gold:#d4a94a; --gold-2:#c2963c;
        --bg:#fbfaf8; --bg-outer:#f0efeb; --card:#ffffff; --border:#e0dfda;
        --text:#262b38; --muted:#6b7280; --ok:#2e9e5b; --ok-bg:#dcf3e4;
        --warn-bg:#f5e7c9; --warn-text:#8a6a1f; --danger:#c0392b; --danger-bg:#f6dcd8;
      }
      /* This PDF path rasterises the on-screen card as-is, bypassing the
         @media print rules entirely — reset the screen-only rounded-corner
         card look here too so the downloaded PDF frames like a printed
         sheet, not a floating app card. */
      #invoice-page-content{border-radius:0 !important;box-shadow:none !important;border:${
        // Minimal's whole point is no boxes — a hard outer frame here would
        // contradict it in the PDF while the browser-print path showed none.
        printThemeFor(lastPreviewInvoice && lastPreviewInvoice.doc_type === "challan") === "minimal"
          ? "none" : "1.5px solid #333"
      } !important;}
      /* #fs-invoice's 460px max-width and .size-a5's 360px max-width are
         both screen-preview caps (keep the on-screen card phone-width and
         centred) — harmless on screen, but this capture is later stretched
         to fill the PDF's full page width (addImage always draws it at
         imgWidth=pageWidth). Left in place, that stretch scales height by
         the SAME factor as width (pageWidth / 360px), which for A5 inflates
         a legitimate one-page-tall layout by ~1.55x and spills it onto a
         second page. Forcing the captured width to the real page width
         up front (mirroring what @media print already does for the browser
         print path) makes the later scale factor ~1:1, so the capture's
         proportions match the physical page instead of being stretched. */
      #fs-invoice{max-width:none !important;}
      /* Height as well as width. The screen min-height is deliberately SHORT
         of the sheet — it subtracts the @page margin and a safety buffer, so
         a browser print does not tip onto a second page. A PDF has neither:
         addImage draws at (0,0) with no margin, so every millimetre of that
         slack became blank paper at the foot of the bill — the "why doesn't
         it reach the bottom" complaint. Here the page IS the sheet, so the
         captured node is stretched to the full page height and the bill ends
         where the paper does. */
      #invoice-page-content{
        max-width:none !important;
        width:${pageWidth}mm !important;
        min-height:${pageHeight}mm !important;
        margin-left:0 !important;margin-right:0 !important;
      }`;
      clonedDoc.head.appendChild(style);
    }
  });
  // A long item list can make the captured canvas taller than one page —
  // slice it into page-height chunks and add each as its own PDF page,
  // rather than the previous Math.min(), which silently cropped anything
  // past the first page instead of continuing onto a second one.
  const pxPerMm = canvas.width / imgWidth;
  const pageHeightPx = Math.round(pageHeight * pxPerMm);
  let renderedPx = 0, firstPage = true;
  while (renderedPx < canvas.height) {
    const sliceHeightPx = Math.min(pageHeightPx, canvas.height - renderedPx);
    const sliceCanvas = document.createElement("canvas");
    sliceCanvas.width = canvas.width;
    sliceCanvas.height = sliceHeightPx;
    sliceCanvas.getContext("2d").drawImage(
      canvas, 0, renderedPx, canvas.width, sliceHeightPx, 0, 0, canvas.width, sliceHeightPx
    );
    if (!firstPage) pdf.addPage();
    pdf.addImage(sliceCanvas.toDataURL("image/png"), "PNG", 0, 0, imgWidth, sliceHeightPx / pxPerMm);
    renderedPx += sliceHeightPx;
    firstPage = false;
  }
  const fname = (lastPreviewInvoice && lastPreviewInvoice.challan_no ? lastPreviewInvoice.challan_no : "invoice") + ".pdf";
  return { pdf, fname };
}
async function downloadInvoicePdf(){
  const btn = document.getElementById("inv-download");
  const originalText = btn.textContent;
  btn.textContent = "⏳ Preparing...";
  btn.disabled = true;
  try{
    const { pdf, fname } = await buildInvoicePdf();
    pdf.save(fname);
  }catch(e){
    console.error("PDF generation failed, falling back to print dialog", e);
    toast("Couldn't build a PDF directly — opening the print dialog instead.");
    window.print();
  }finally{
    btn.textContent = originalText;
    btn.disabled = false;
  }
}
/**
 * "Share as PDF" on WhatsApp — the ONLY way a web page can hand an actual
 * file to WhatsApp specifically (wa.me only ever pre-fills text, it has no
 * concept of an attachment) is the native Web Share API, which opens the
 * device's own share sheet; the user picks WhatsApp (Messenger OR Business —
 * both show up there if installed, which is the OS's job, not this page's)
 * from whatever's registered to accept a PDF. Desktop browsers and older
 * mobile browsers don't support sharing files this way, so this falls back
 * to just downloading the PDF and telling the user to attach it manually.
 */
async function shareInvoicePdfWhatsApp(){
  const btn = document.getElementById("inv-whatsapp-pdf");
  if(!btn) return;
  const originalText = btn.textContent;
  btn.textContent = "⏳ Preparing...";
  btn.disabled = true;
  try{
    const { pdf, fname } = await buildInvoicePdf();
    const blob = pdf.output("blob");
    const file = new File([blob], fname, { type: "application/pdf" });
    if(navigator.canShare && navigator.canShare({ files: [file] })){
      await navigator.share({ files: [file], title: fname });
    } else {
      pdf.save(fname);
      toast("Your browser can't hand a file straight to WhatsApp — the PDF downloaded instead, attach it from there.");
    }
  }catch(e){
    if(e && e.name === "AbortError") return; // user cancelled the share sheet — not an error
    console.error("Share-as-PDF failed", e);
    toast("Couldn't share the PDF. Try Download PDF and attach it manually.");
  }finally{
    btn.textContent = originalText;
    btn.disabled = false;
  }
}
/**
 * "Print to Shop Printer" — asks the SAME server this phone is already
 * talking to, to silently print the invoice on the shop PC's USB printer
 * (see server/routes/print.js). Shows Printing… while the job is queued/
 * running, then Printed Successfully or the specific reason it failed
 * (printer offline, out of paper, helper not installed, etc) — polling
 * rather than waiting on one long request, since real printing can take
 * longer than any request should stay open.
 */
async function printViaServer(){
  const inv = lastPreviewInvoice;
  if(!inv || !inv.id){ toast("Complete the sale first — printing needs a saved invoice."); return; }
  const btn = document.getElementById("inv-server-print");
  const statusRow = document.getElementById("print-status-row");
  const setStatus = (text, cls) => {
    if(!statusRow) return;
    statusRow.style.display = "block";
    statusRow.textContent = text;
    statusRow.className = "print-status-row" + (cls ? " "+cls : "");
  };

  btn.disabled = true;
  setStatus("🖨 Printing…");
  try{
    const job = await api("POST", "/print", { invoiceId: inv.id, showRate: state.challanShowRate });
    const jobId = job.jobId;

    // Poll every 1s for up to 30s — a real print job is typically done in a
    // few seconds, but a slow/busy printer shouldn't be cut off early.
    for(let i=0; i<30; i++){
      await new Promise(r=>setTimeout(r,1000));
      const status = await api("GET", `/print/jobs/${jobId}`);
      if(status.status === "done"){
        setStatus("✅ Printed successfully.", "ok");
        btn.disabled = false;
        return;
      }
      if(status.status === "failed"){
        setStatus("❌ "+(status.error||"Printing failed."), "error");
        btn.disabled = false;
        return;
      }
      // still queued/printing — keep waiting
    }
    setStatus("⏳ Still printing — check the shop PC if this doesn't finish.", "");
  }catch(err){
    setStatus("❌ "+err.message, "error");
  }finally{
    btn.disabled = false;
  }
}

/**
 * Single entry point for every WhatsApp link in the app — `phone` (any
 * format, digits extracted and prefixed with the India country code) opens
 * that chat directly, without needing the number saved as a contact; omit
 * it to open WhatsApp's own chat list. `text`, if given, arrives pre-filled
 * in the message box.
 *
 * wa.me already degrades sensibly on its own: no WhatsApp Desktop app on a
 * PC falls back to WhatsApp Web in a new tab, and on a phone the OS (not
 * this page) owns whatever happens when no WhatsApp app is registered for
 * the link — a web page has no API to ask "is WhatsApp installed?", so
 * this doesn't try to fake that check. The one failure a page CAN detect
 * is a popup blocker silently eating window.open, which is what the toast
 * below actually covers.
 */
function openWhatsApp(phone, text){
  const num = phone ? "91" + String(phone).replace(/\D/g,"") : "";
  const url = "https://wa.me/" + num + (text ? ("?text=" + encodeURIComponent(text)) : "");
  const win = window.open(url, "_blank");
  if(!win) toast("Couldn't open WhatsApp — allow pop-ups for this site, or install WhatsApp to use this.");
}

/* ============================================================
   REPORTS
   ============================================================ */
/* ============================================================
   PREVIOUS / NEXT BILL NAVIGATION
   ------------------------------------------------------------
   Checking bills one by one used to mean: open a bill, read it,
   close it, find the next row, open that. This keeps the list's
   ORDER in memory when a bill is opened, so the detail screen
   can step straight to the neighbouring bill.

   The order is whatever the list was showing — including its
   date filter — rather than a fresh server sort. If the list is
   filtered to August, Next walks August's bills and stops at
   the end of them, which is what someone checking August
   actually wants.

   Held in memory only: reopening a bill from somewhere with no
   list behind it (a supplier's ledger, a search result) simply
   shows no arrows rather than stepping through an order the
   user never chose.
   ============================================================ */
const billNav = { kind: null, rows: [] };

/** Called by a list right before it opens a bill. `rows` must be in the order
 *  shown on screen, each with { id, no, date, party, total }. */
function setBillNav(kind, rows){
  billNav.kind = kind;
  billNav.rows = Array.isArray(rows) ? rows : [];
}

function billNavPosition(kind, id){
  if(billNav.kind !== kind) return null;
  const i = billNav.rows.findIndex(r => String(r.id) === String(id));
  return i < 0 ? null : { index: i, total: billNav.rows.length,
                          prev: billNav.rows[i-1] || null, next: billNav.rows[i+1] || null };
}

/** The bar itself. Returns "" when there's no list context, so a bill opened
 *  from elsewhere is unchanged. */
function billNavHtml(kind, id){
  const pos = billNavPosition(kind, id);
  if(!pos || pos.total < 2) return "";
  const label = r => r ? escapeHtml(r.no || "—") : "";
  const btn = (dir, r) => `
    <button class="btn btn-outline" data-billnav="${dir}" ${r?"":"disabled"}
      style="flex:1;min-width:0;padding:7px 8px;font-size:11.5px;line-height:1.3;${r?"":"opacity:.45;"}">
      <div style="font-weight:800;">${dir==="prev"?"← Previous":"Next →"}</div>
      <div class="muted" style="font-size:10.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${r?label(r):"—"}</div>
    </button>`;
  return `
    <div class="card" style="margin-bottom:10px;padding:8px;">
      <div style="display:flex;gap:8px;align-items:stretch;">
        ${btn("prev", pos.prev)}
        <div style="flex:0 0 auto;display:flex;flex-direction:column;justify-content:center;align-items:center;padding:0 6px;">
          <div style="font-weight:800;font-size:12px;white-space:nowrap;">Bill ${pos.index+1} of ${pos.total}</div>
          ${pos.prev||pos.next ? `<div class="muted" style="font-size:10px;">tap to step</div>` : ""}
        </div>
        ${btn("next", pos.next)}
      </div>
    </div>`;
}

/** Wires the two arrows inside `root` to reopen the neighbouring bill. */
function wireBillNav(root, kind, id, open){
  const pos = billNavPosition(kind, id);
  if(!pos) return;
  root.querySelectorAll("[data-billnav]").forEach(b=>{
    b.addEventListener("click", ()=>{
      const target = b.dataset.billnav === "prev" ? pos.prev : pos.next;
      if(target) open(target.id);
    });
  });
}

/**
 * Keeps the Billing screen honest about its date. The field defaults to today
 * and the chosen date survives a save (so a stack of old paper bills can be
 * entered in one go) — which means the only thing stopping the next real sale
 * being backdated by accident is that the screen says so, loudly.
 */
function syncBillingDateWarning(){
  const input = document.getElementById("billing-date");
  const warn = document.getElementById("billing-date-warning");
  if(!input || !warn) return;
  if(!input.value) input.value = isoDate(new Date());
  const today = isoDate(new Date());
  if(input.value === today){ warn.style.display = "none"; warn.innerHTML = ""; return; }
  const pretty = new Date(input.value+"T00:00:00").toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"});
  warn.style.display = "block";
  warn.innerHTML = `<div style="margin-top:8px;padding:9px 11px;border-radius:9px;background:var(--warn-bg);color:var(--warn-text);font-size:11.5px;font-weight:700;display:flex;justify-content:space-between;align-items:center;gap:8px;">
    <span>Dated ${escapeHtml(pretty)}, not today.</span>
    <a href="#" id="billing-date-today" style="color:var(--warn-text);font-weight:800;white-space:nowrap;">Use today</a>
  </div>`;
  const link = document.getElementById("billing-date-today");
  if(link) link.addEventListener("click", e=>{
    e.preventDefault();
    input.value = isoDate(new Date());
    syncBillingDateWarning();
  });
}

/* ---------- Reports date range ----------
   Stock and dues reports are point-in-time balances — what is on the shelf,
   what is owed, right now — so a date range can't narrow them into anything
   meaningful. They get no date bar rather than a control that silently does
   nothing (or worse, looks like it worked). */
const REPORT_IGNORES_DATE = new Set(["Stock", "Customer", "LocationStock", "BalanceSheet"]);

/** Local-date YYYY-MM-DD — deliberately not toISOString(), which is UTC and
 *  in India rolls "today" back a day before 5:30am. Matches the server's
 *  todayStr(). */
function isoDate(d){
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
}

/** `?from=..&to=..` for a bare path, or `&from=..` when the URL already has a
 *  query (export, party-product). Empty string when showing all time. */
function reportRangeQS(hasQuery){
  const p = [];
  if(state.repFrom) p.push("from="+encodeURIComponent(state.repFrom));
  if(state.repTo) p.push("to="+encodeURIComponent(state.repTo));
  if(!p.length) return "";
  return (hasQuery ? "&" : "?") + p.join("&");
}

/* The same period the report is showing, as an object rather than a query
   string. A drill-down that used a different range from the total it was
   opened from would be worse than no drill-down: the reader would trust
   it. Built from the same two pieces of state as reportRangeQS above, so
   the two cannot disagree. */
function reportRangeParams(){
  const p = {};
  if(state.repFrom) p.from = state.repFrom;
  if(state.repTo) p.to = state.repTo;
  return p;
}

function setReportRange(from, to, period){
  state.repFrom = from || "";
  state.repTo = to || "";
  // No period means a hand-typed range: no preset chip should stay lit.
  state.repPeriod = period || "";
  syncReportDateBar();
  renderReport();
}

function applyReportPeriod(period){
  const today = new Date();
  const daysAgo = n => { const x = new Date(); x.setDate(x.getDate()-n); return x; };
  let from = "", to = "";
  if(period==="today"){ from = to = isoDate(today); }
  else if(period==="yesterday"){ from = to = isoDate(daysAgo(1)); }
  else if(period==="7"){ from = isoDate(daysAgo(6)); to = isoDate(today); }   // inclusive of today
  else if(period==="30"){ from = isoDate(daysAgo(29)); to = isoDate(today); }
  else if(period==="thismonth"){ from = isoDate(new Date(today.getFullYear(), today.getMonth(), 1)); to = isoDate(today); }
  else if(period==="lastmonth"){
    from = isoDate(new Date(today.getFullYear(), today.getMonth()-1, 1));
    to   = isoDate(new Date(today.getFullYear(), today.getMonth(), 0)); // day 0 = last of previous month
  }
  setReportRange(from, to, period);
}

/** True when the range is exactly one whole calendar month, so the month
 *  picker can show it without contradicting a From/To that means something
 *  else. */
function isWholeMonth(from, to){
  if(!from || !to || !from.endsWith("-01")) return false;
  const [y, m] = from.split("-").map(Number);
  return to === isoDate(new Date(y, m, 0));
}

function describeReportRange(){
  if(!state.repFrom && !state.repTo) return "Showing all dates.";
  const pretty = s => s ? new Date(s+"T00:00:00").toLocaleDateString("en-IN",{day:"numeric",month:"short",year:"numeric"}) : "";
  if(state.repFrom && state.repTo){
    return state.repFrom===state.repTo
      ? `Showing ${pretty(state.repFrom)} only.`
      : `Showing ${pretty(state.repFrom)} to ${pretty(state.repTo)}.`;
  }
  return state.repFrom ? `Showing ${pretty(state.repFrom)} onwards.` : `Showing up to ${pretty(state.repTo)}.`;
}

function syncReportDateBar(){
  document.querySelectorAll('[data-period]').forEach(x=>
    x.classList.toggle("selected", x.dataset.period===state.repPeriod));
  const f = document.getElementById("rep-from"), t = document.getElementById("rep-to"), m = document.getElementById("rep-month");
  if(f) f.value = state.repFrom;
  if(t) t.value = state.repTo;
  if(m) m.value = isWholeMonth(state.repFrom, state.repTo) ? state.repFrom.slice(0,7) : "";
  const label = document.getElementById("rep-range-label");
  if(label) label.textContent = describeReportRange();
}

async function renderReport(){
  const body = document.getElementById("report-body");
  const dateBar = document.getElementById("report-date-bar");
  if(dateBar) dateBar.style.display = REPORT_IGNORES_DATE.has(state.reportType) ? "none" : "block";
  syncReportDateBar();
  // The acknowledgement filter only applies to challans — keep it out of the
  // way on every other report rather than showing a control that does nothing.
  const ackFilter = document.getElementById("challan-ack-filter");
  if(ackFilter) ackFilter.style.display = state.reportType==="Challan" ? "flex" : "none";
  try{
    if(state.reportType==="Purchase") { await renderPurchaseReport(body); return finishReport(body); }
    if(state.reportType==="Challan") { await renderChallanReport(body); return finishReport(body); }
    if(state.reportType==="Orders") { await renderOrdersReport(body); return finishReport(body); }
    if(state.reportType==="TaxInvoice") { await renderTaxInvoiceReport(body); return finishReport(body); }
    if(state.reportType==="PurchaseBill") { await renderPurchaseBillReport(body); return finishReport(body); }
    if(state.reportType==="PurchaseOrders") { await renderPoReport(body); return finishReport(body); }
    if(state.reportType==="Salesman") { await renderSalesmanReport(body); return finishReport(body); }
    if(state.reportType==="Area") { await renderAreaReport(body); return finishReport(body); }
    if(state.reportType==="Party") { await renderPartyReport(body); return finishReport(body); }
    if(state.reportType==="PartyProduct") { await renderPartyProductReport(body); return finishReport(body); }
    if(state.reportType==="Profit") { await renderProfitReport(body); return finishReport(body); }
    if(state.reportType==="ProfitByInvoice") { await renderProfitByInvoiceReport(body); return finishReport(body); }
    if(state.reportType==="Supplier") { await renderSupplierReport(body); return finishReport(body); }
    if(state.reportType==="SalePayments") { await renderSalePaymentsReport(body); return finishReport(body); }
    if(state.reportType==="PurchasePayments") { await renderPurchasePaymentsReport(body); return finishReport(body); }
    if(state.reportType==="LocationStock") { await renderLocationStockReport(body); return finishReport(body); }
    if(state.reportType==="Transfers") { await renderTransfersReport(body); return finishReport(body); }
    if(state.reportType==="DailyMovement") { await renderDailyMovementReport(body); return finishReport(body); }
    if(state.reportType==="BalanceSheet") { await renderBalanceSheetReport(body); return finishReport(body); }
    if(state.reportType==="ProfitLoss") { await renderPnlReport(body); return finishReport(body); }

    let title="", subtitle="", rows=[];
    if(state.reportType==="Sales"){
      title = "Sales by Payment Method"; subtitle="Total invoice value";
      rows = await api("GET","/reports/sales-by-payment"+reportRangeQS());
    } else if(state.reportType==="GST"){
      title="GST Collected";
      subtitle = "CGST + SGST + IGST across " + (state.repFrom||state.repTo ? "invoices in the selected period" : "all invoices");
      const g = await api("GET","/reports/gst"+reportRangeQS());
      rows = [{label:"CGST", value:g.cgst}, {label:"SGST", value:g.sgst}, {label:"IGST", value:g.igst}].filter(r=>r.value>0);
    } else if(state.reportType==="Stock"){
      title="Stock by Brand"; subtitle="Units currently on hand";
      rows = await api("GET","/reports/stock-by-brand");
    } else if(state.reportType==="Brand"){
      title="Sales by Brand"; subtitle="Revenue from priced invoices, by product brand";
      rows = await api("GET","/reports/brand-wise"+reportRangeQS());
    } else {
      title="Customer Outstanding"; subtitle="Dues by customer";
      rows = await api("GET","/reports/customer-dues");
    }
    const max = Math.max(1, ...rows.map(r=>r.value));
    body.innerHTML = `<div style="font-weight:800;font-size:14px;">${title}</div><div class="muted" style="font-size:11.5px;margin-bottom:10px;">${subtitle}</div>` +
      /* Recording what has been filed belongs where the owner is already
         looking at GST, not buried in Settings. */
      (state.reportType==="GST" && isOwner()
        ? `<button class="btn btn-outline" id="gst-filings-btn" style="margin-bottom:12px;">Which returns have I filed?</button>`
        : "") +
      (rows.length ? rows.map(r=>`
        <div style="margin-bottom:10px;">
          <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;font-size:12px;font-weight:700;margin-bottom:4px;">
            <span>${escapeHtml(r.label)}</span>
            <span style="display:flex;align-items:center;gap:6px;"><span>${state.reportType==="Stock"?r.value+" units":fmt(r.value)}</span>
            ${drillBtn(`${r.label} — ${title}`, { ...reportRangeParams(), ...(state.reportType==="Stock" ? { brand: r.label } : {}) }, "The bills and purchases behind this figure")}</span>
          </div>
          <div style="height:8px;background:var(--bg-outer);border-radius:100px;"><div style="height:100%;width:${(r.value/max)*100}%;background:var(--navy);border-radius:100px;"></div></div>
        </div>`).join("") : `<div class="empty-hint">No data yet for this report.</div>`);
    await finishReport(body);
  }catch(e){ toast(e.message); }
}

async function renderPurchaseReport(body){
  const rows = await api("GET","/reports/purchases"+reportRangeQS());
  body.innerHTML = `<div style="font-weight:800;font-size:14px;">Purchase Report</div><div class="muted" style="font-size:11.5px;margin-bottom:10px;">Every stock-in recorded, newest first</div>` +
    (rows.length ? rows.map(r=>`
      <div class="list-row" ${r.source==="purchase"
        ? `style="cursor:pointer;" data-open-purchase="${r.doc_id}" data-doc-name="${escapeHtml(r.doc_no||"")}"`
        : `style="cursor:pointer;" data-open-stock-in="${r.doc_id}" data-doc-name="${escapeHtml(r.product_name||"")}"`}><div>
        <div class="row-title">${escapeHtml(r.product_name)}${r.size_label?" · "+escapeHtml(r.size_label):""}</div>
        ${r.source==="purchase" ? `<div class="row-sub muted">One line of purchase ${escapeHtml(r.doc_no||"")} — acting on it acts on the whole bill</div>` : ""}
        <div class="row-sub">${escapeHtml(r.purchase_date||"")}${r.invoice_no?" · Inv# "+escapeHtml(r.invoice_no):""}${r.supplier?" · "+escapeHtml(r.supplier):""}</div>
        <div class="row-sub">${r.qty} pcs${r.billed_qty&&r.billed_qty!==r.qty?" · "+Pricing.formatQty(r.billed_qty, r.mode||"UNIT"):""}</div>
      </div><div class="row-right row-title">${fmt(r.grand_total)}</div></div>
    `).join("") : `<div class="empty-hint">No purchases recorded yet.</div>`);
}

const CHALLAN_STATUS_PILL = { Pending: "warn", Billed: "ok" };
async function renderChallanReport(body){
  const all = await api("GET","/reports/challans"+reportRangeQS());
  // Acknowledgement is a sales-challan concept — a Purchase Challan is goods
  // coming IN, there's no customer signature to chase — so filtering by it
  // narrows to sales rows only rather than silently dropping purchase rows
  // from an "All" view.
  const f = state.challanAckFilter || "all";
  const rows = f === "all" ? all : all.filter(r=>r.type==="Sales" && r.ackStatus===(f==="received"?"Received":"Pending"));
  const emptyMsg = f==="all" ? "No challans recorded yet."
    : f==="pending" ? "No challans are waiting for acknowledgement."
    : "No acknowledged challans yet.";
  body.innerHTML = `<div style="font-weight:800;font-size:14px;">Challan Report</div><div class="muted" style="font-size:11.5px;margin-bottom:10px;">Every Delivery Challan (sales) and Purchase Challan (goods received), newest first — tap a row to open it</div>` +
    (rows.length ? rows.map(r=>`
      <div class="list-row" style="cursor:pointer;" ${r.type==="Sales"?`data-open-invoice="${r.id}"`:`data-open-purchase="${r.id}"`}><div>
        <div class="row-title">${escapeHtml(r.challan_no)} <span class="pill ${r.type==="Sales"?"ok":"warn"}" style="font-size:9.5px;">${r.type}</span></div>
        <div class="row-sub">${escapeHtml(r.date)} · ${escapeHtml(r.party_name||(r.type==="Sales"?"Walk-in":"Unknown Supplier"))}</div>
        <div class="row-sub">${r.item_count} item${r.item_count!==1?"s":""} · ${r.total_pieces} pcs${(r.transport||r.loading)?" · Transport+Loading "+fmt((r.transport||0)+(r.loading||0)):""}</div>
      </div>${r.type==="Sales"?`<div class="row-right" style="text-align:right;">
        <div><span class="pill ${r.ackStatus==="Received"?"ok":"warn"}" style="font-size:9.5px;">${r.ackStatus==="Received"?"🟢 Received":"🟡 Pending"}</span></div>
        <div style="margin-top:3px;"><span class="pill ${CHALLAN_STATUS_PILL[r.status]||''}" style="font-size:9px;">${escapeHtml(r.status)}</span></div>
      </div>`:""}</div>
    `).join("") : `<div class="empty-hint">${emptyMsg}</div>`);
  // This list mixes sales and purchase challans, which live on different
  // screens. The navigation order is therefore built at click time from the
  // rows of the SAME type, so Next never jumps between the two.
  const navRows = type => rows.filter(r=>r.type===type).map(r=>({
    id: r.id, no: r.challan_no, date: r.date, party: r.party_name, total: r.total
  }));
  body.querySelectorAll("[data-open-invoice]").forEach(el=>{
    el.addEventListener("click", ()=>{
      setBillNav("invoice", navRows("Sales"));
      openExistingInvoice(el.dataset.openInvoice);
    });
  });
  body.querySelectorAll("[data-open-purchase]").forEach(el=>{
    el.addEventListener("click", ()=>{
      setBillNav("purchase", navRows("Purchase"));
      openPurchaseDetail(el.dataset.openPurchase);
    });
  });
}
async function renderOrdersReport(body){
  const rows = await api("GET","/reports/orders"+reportRangeQS());
  // Three document types share this list, so the row attribute, the type pill
  // and the status pill all key off r.type rather than a Sales/not-Sales guess.
  const openAttr = r => r.type==="Sales" ? `data-open-so="${r.id}"`
                    : r.type==="Quotation" ? `data-open-quotation="${r.id}"`
                    : `data-open-po="${r.id}"`;
  const typePill = r => r.type==="Sales" ? "ok" : r.type==="Quotation" ? "" : "warn";
  const statusPill = r => (r.type==="Sales" ? SO_STATUS_PILL
                         : r.type==="Quotation" ? QUOTATION_STATUS_PILL
                         : PO_STATUS_PILL)[r.status] || "";
  const partyFallback = r => r.type==="Purchase" ? "Unknown Supplier" : "Walk-in";

  body.innerHTML = `<div style="font-weight:800;font-size:14px;">Orders Report</div><div class="muted" style="font-size:11.5px;margin-bottom:10px;">Every Quotation, Purchase Order and Sales Order, newest first — tap a row to open it</div>` +
    (rows.length ? rows.map(r=>`
      <div class="list-row" style="cursor:pointer;" ${openAttr(r)}><div>
        <div class="row-title">${escapeHtml(r.order_no)} <span class="pill ${typePill(r)}" style="font-size:9.5px;">${r.type}</span></div>
        <div class="row-sub">${escapeHtml(r.date)} · ${escapeHtml(r.party_name||partyFallback(r))}</div>
      </div><div class="row-right"><div class="row-title">${fmt(r.total)}</div><span class="pill ${statusPill(r)}">${escapeHtml(r.status)}</span></div></div>
    `).join("") : `<div class="empty-hint">No quotations or orders recorded yet.</div>`);
  body.querySelectorAll("[data-open-quotation]").forEach(el=>{
    el.addEventListener("click", ()=>openQuotationDetail(el.dataset.openQuotation));
  });
  body.querySelectorAll("[data-open-po]").forEach(el=>{
    el.addEventListener("click", ()=>openPoDetail(el.dataset.openPo));
  });
  body.querySelectorAll("[data-open-so]").forEach(el=>{
    el.addEventListener("click", ()=>openSoDetail(el.dataset.openSo));
  });
}
async function renderTaxInvoiceReport(body){
  const rows = await api("GET","/reports/tax-invoices"+reportRangeQS());
  body.innerHTML = `<div style="font-weight:800;font-size:14px;">Tax Invoice Report</div><div class="muted" style="font-size:11.5px;margin-bottom:10px;">Every Tax Invoice issued, newest first — tap a row to open it</div>` +
    (rows.length ? rows.map(r=>`
      <div class="list-row" style="cursor:pointer;" data-open-invoice="${r.id}"><div>
        <div class="row-title">${escapeHtml(r.challan_no)}</div>
        <div class="row-sub">${escapeHtml(r.date)} · ${escapeHtml(r.customer_name||"Walk-in")} · ${escapeHtml(r.payment_method)}</div>
        ${r.balance_due>0?`<div class="row-sub" style="color:var(--danger);">Due ${fmt(r.balance_due)}</div>`:""}
      </div><div class="row-right row-title">${fmt(r.total)}</div></div>
    `).join("") : `<div class="empty-hint">No tax invoices issued yet.</div>`);
  setBillNav("invoice", rows.map(r=>({
    id: r.id, no: r.challan_no, date: r.date, party: r.customer_name, total: r.total
  })));
  body.querySelectorAll("[data-open-invoice]").forEach(el=>{
    el.addEventListener("click", ()=>openExistingInvoice(el.dataset.openInvoice));
  });
}
async function renderPurchaseBillReport(body){
  const rows = await api("GET","/reports/purchase-bills"+reportRangeQS());
  body.innerHTML = `<div style="font-weight:800;font-size:14px;">Purchase Bill Report</div><div class="muted" style="font-size:11.5px;margin-bottom:10px;">Every purchase bill recorded, newest first — tap a row to open it</div>` +
    (rows.length ? rows.map(r=>`
      <div class="list-row" ${r.source==="purchase"?`style="cursor:pointer;" data-open-purchase="${r.id}"`:""}><div>
        <div class="row-title">${escapeHtml(r.bill_no||"—")}</div>
        <div class="row-sub">${escapeHtml(r.date||"")} · ${escapeHtml(r.supplier_name||"Unknown Supplier")} · ${r.item_count} item${r.item_count!==1?"s":""}</div>
      </div><div class="row-right row-title">${fmt(r.grand_total)}</div></div>
    `).join("") : `<div class="empty-hint">No purchase bills recorded yet.</div>`);
  // Only rows that can actually be opened go into the navigation order —
  // otherwise Next would land on a stock-in row that has no bill screen.
  setBillNav("purchase", rows.filter(r=>r.source==="purchase").map(r=>({
    id: r.id, no: r.bill_no, date: r.date, party: r.supplier_name, total: r.grand_total
  })));
  body.querySelectorAll("[data-open-purchase]").forEach(el=>{
    el.addEventListener("click", ()=>openPurchaseDetail(el.dataset.openPurchase));
  });
}
/* ============================================================
   PURCHASE ORDER REPORTS

   Nine views of one chain, so they live under one report rather than nine
   chips in a row that already runs off the side of a phone. The chip row
   picks which question is being asked; the range picker above it already
   decides over what period.

   Every figure comes from the server's own line-level queries — nothing is
   summed here — so the number on screen and the number in an export cannot
   drift apart.
   ============================================================ */
const PO_REPORT_VIEWS = [
  ["party",    "Party-wise"],
  ["salesman", "Salesman-wise"],
  ["supplier", "Supplier-wise"],
  ["brand",    "Brand-wise"],
  ["product",  "Product-wise"],
  ["pending",  "Pending"],
  ["completed","Completed"],
  ["date",     "Date-wise"],
  ["sovspo",   "Order vs PO"]
];

async function renderPoReport(body){
  if(!state.poReportView) state.poReportView = "party";

  body.innerHTML = `
    <div style="font-weight:800;font-size:14px;">Purchase Orders</div>
    <div class="muted" style="font-size:11.5px;margin-bottom:8px;">
      Salesman → party → sales order → purchase order → supplier → goods
    </div>
    <div class="muted" style="font-size:11px;margin:-4px 0 8px;">
      Rows that name an order open it — from there you can edit, cancel or delete it.
    </div>
    <div class="chip-row" id="po-report-views" style="margin-bottom:10px;">
      ${PO_REPORT_VIEWS.map(([k,l])=>`<button class="chip ${k===state.poReportView?"selected":""}" data-po-report="${k}">${l}</button>`).join("")}
    </div>
    <div id="po-report-body"><p class="muted" style="font-size:13px;">Loading…</p></div>`;

  body.querySelectorAll("[data-po-report]").forEach(b => b.addEventListener("click", ()=>{
    state.poReportView = b.dataset.poReport;
    renderPoReport(body);
  }));

  const into = document.getElementById("po-report-body");
  try{ await PO_REPORT_RENDERERS[state.poReportView](into); }
  catch(e){ into.innerHTML = `<p class="muted" style="font-size:13px;">${escapeHtml(e.message)}</p>`; }
}

/* A bar chart of one labelled column. Used by the five "grouped by" views,
   which differ only in what they group and what the second figure says. */
function poBarRows(rows, valueKey, subLine){
  if(!rows.length) return `<div class="empty-hint">Nothing in this period.</div>`;
  const max = Math.max(1, ...rows.map(r => Number(r[valueKey]) || 0));
  return rows.map(r => `
    <div style="margin-bottom:10px;">
      <div style="display:flex;justify-content:space-between;gap:8px;font-size:12px;font-weight:700;margin-bottom:4px;">
        <span style="min-width:0;overflow-wrap:anywhere;">${escapeHtml(r.label || "—")}</span>
        <span style="white-space:nowrap;">${escapeHtml(subLine(r))}</span>
      </div>
      <div style="height:8px;background:var(--bg-outer);border-radius:100px;">
        <div style="height:100%;width:${(Number(r[valueKey])||0)/max*100}%;background:var(--navy);border-radius:100px;"></div>
      </div>
    </div>`).join("");
}

/** A plain table that scrolls sideways inside itself on a phone. */
/** A plain table that scrolls sideways inside itself on a phone.
 *
 *  Pass `openId` and each row becomes a way into the order it names, so
 *  the report can hand the shop straight to the thing it is reporting on
 *  rather than leaving them to hunt for it. */
function poTable(head, rows, cells, openId){
  if(!rows.length) return `<div class="empty-hint">Nothing in this period.</div>`;
  return `<div style="overflow-x:auto;">
    <table class="rep-table" style="width:100%;border-collapse:collapse;font-size:11.5px;white-space:nowrap;">
      <thead><tr>${head.map(h=>`<th style="text-align:left;padding:5px 8px;border-bottom:1px solid var(--border);">${escapeHtml(h)}</th>`).join("")}</tr></thead>
      <tbody>${rows.map(r=>{
        const id = openId ? openId(r) : null;
        return `<tr${id ? ` data-po-open="${escapeHtml(id)}" style="cursor:pointer;"` : ""}>` +
          cells(r).map(c=>`<td style="padding:5px 8px;border-bottom:1px solid var(--border);">${c}</td>`).join("") +
        `</tr>`;
      }).join("")}</tbody>
    </table></div>`;
}

/** Wire whatever rows in `box` name an order. */
function wirePoOpeners(box){
  box.querySelectorAll("[data-po-open]").forEach(el => el.addEventListener("click", ()=>{
    openPoDetail(el.dataset.poOpen);
  }));
}

const poQty = n => Pricing.trimNum(round2(Number(n) || 0));

const PO_REPORT_RENDERERS = {
  async party(into){
    const rows = await api("GET","/reports/po-party-wise"+reportRangeQS());
    into.innerHTML = `<div class="muted" style="font-size:11.5px;margin-bottom:8px;">What has been bought in for each customer, and what they are still waiting on.</div>` +
      poBarRows(rows, "value", r =>
        `${fmt(r.value)} · ${r.orders} PO${r.orders===1?"":"s"}` +
        (r.pending > 0 ? ` · ${poQty(r.pending)} pending` : ""));
  },

  async salesman(into){
    const rows = await api("GET","/reports/po-salesman-wise"+reportRangeQS());
    into.innerHTML = `<div class="muted" style="font-size:11.5px;margin-bottom:8px;">Tap a name to see that salesman's own orders.</div>` +
      poBarRows(rows, "value", r =>
        `${fmt(r.value)} · ${r.orders} PO${r.orders===1?"":"s"} · ${r.parties} part${r.parties===1?"y":"ies"}`) +
      `<div class="chip-row" style="margin-top:6px;">
        ${rows.map(r=>`<button class="chip" data-po-sm="${escapeHtml(r.label)}">${escapeHtml(r.label)}</button>`).join("")}
      </div>
      <div id="po-sm-detail"></div>`;

    into.querySelectorAll("[data-po-sm]").forEach(b => b.addEventListener("click", async ()=>{
      into.querySelectorAll("[data-po-sm]").forEach(x=>x.classList.toggle("selected", x===b));
      const box = document.getElementById("po-sm-detail");
      box.innerHTML = `<p class="muted" style="font-size:12px;">Loading…</p>`;
      const list = await api("GET","/reports/po-salesman-detail?salesman="+encodeURIComponent(b.dataset.poSm)+reportRangeQS(true));
      box.innerHTML = `<div class="section-title">${escapeHtml(b.dataset.poSm)}</div>` +
        poTable(["PO","Date","Party","Sales Order","Supplier","Status","Value"], list, r => [
          escapeHtml(r.po_no), r.date, escapeHtml(r.party||"—"), escapeHtml(r.so_no||"—"),
          escapeHtml(r.supplier||"—"), escapeHtml(r.status), fmt(r.value)
        ], r => r.id);
      wirePoOpeners(box);
    }));
  },

  async supplier(into){
    const rows = await api("GET","/reports/po-supplier-wise"+reportRangeQS());
    into.innerHTML = poBarRows(rows, "value", r =>
      `${fmt(r.value)} · ${r.orders} PO${r.orders===1?"":"s"}` + (r.pending>0?` · ${poQty(r.pending)} pending`:""));
  },

  async brand(into){
    const rows = await api("GET","/reports/po-brand-wise"+reportRangeQS());
    into.innerHTML = poBarRows(rows, "value", r =>
      `${fmt(r.value)} · ${poQty(r.qty)} ordered` + (r.pending>0?` · ${poQty(r.pending)} pending`:""));
  },

  async product(into){
    const rows = await api("GET","/reports/po-product-wise"+reportRangeQS());
    into.innerHTML = poTable(["Product","Brand","Size","Ordered","Received","Pending","Value"], rows, r => [
      escapeHtml(r.label), escapeHtml(r.brand||"—"), escapeHtml(r.size||"—"),
      poQty(r.qty), poQty(r.received),
      r.pending > 0 ? `<b style="color:var(--danger);">${poQty(r.pending)}</b>` : "—",
      fmt(r.value)
    ]);
  },

  async pending(into){
    const rows = await api("GET","/reports/po-pending"+reportRangeQS());
    const total = rows.reduce((t,r)=>t+(Number(r.pending)||0), 0);
    into.innerHTML =
      `<div class="card" style="margin-top:0;margin-bottom:8px;">
        <div class="row-title">${poQty(total)} still to come in</div>
        <div class="row-sub">Across ${rows.length} line${rows.length===1?"":"s"}, oldest promise first.</div>
      </div>` +
      poTable(["Due","PO","Party","Salesman","Product","Ordered","Received","Pending","Supplier"], rows, r => [
        escapeHtml(r.required_delivery_date || r.expected_delivery_date || r.date),
        escapeHtml(r.po_no), escapeHtml(r.party||"—"), escapeHtml(r.salesman||"—"),
        escapeHtml(r.name) + (r.brand?` <span class="muted">${escapeHtml(r.brand)}</span>`:""),
        poQty(r.qty), poQty(r.received_qty),
        `<b style="color:var(--danger);">${poQty(r.pending)}</b>`,
        escapeHtml(r.supplier||"—")
      ], r => r.po_id);
    wirePoOpeners(into);
  },

  async completed(into){
    const rows = await api("GET","/reports/po-completed"+reportRangeQS());
    into.innerHTML = poTable(["PO","Date","Party","Salesman","Supplier","Value"], rows, r => [
      escapeHtml(r.po_no), r.date, escapeHtml(r.party||"—"),
      escapeHtml(r.salesman||"—"), escapeHtml(r.supplier||"—"), fmt(r.value)
    ], r => r.id);
    wirePoOpeners(into);
  },

  async date(into){
    const rows = await api("GET","/reports/po-date-wise"+reportRangeQS());
    into.innerHTML = poBarRows(rows, "value", r => `${fmt(r.value)} · ${r.orders} PO${r.orders===1?"":"s"}`);
  },

  async sovspo(into){
    const rows = await api("GET","/reports/po-so-vs-po"+reportRangeQS());
    into.innerHTML =
      `<div class="muted" style="font-size:11.5px;margin-bottom:8px;">
        What was promised against what was bought in. A blank PO column is a sales order nobody ordered material for.
      </div>` +
      poTable(["Sales Order","Date","Party","Ordered","On PO","Received","Short","Purchase Orders"], rows, r => {
        const short = round2((Number(r.ordered_qty)||0) - (Number(r.po_qty)||0));
        return [
          escapeHtml(r.so_no), r.date, escapeHtml(r.party||"—"),
          poQty(r.ordered_qty), poQty(r.po_qty), poQty(r.received_qty),
          short > 0.0001 ? `<b style="color:var(--danger);">${poQty(short)}</b>` : "—",
          escapeHtml(r.po_nos || "—")
        ];
      });
  }
};

async function renderSalesmanReport(body){
  const rows = await api("GET","/reports/salesman-wise"+reportRangeQS());
  const max = Math.max(1, ...rows.map(r=>r.value));
  body.innerHTML = `<div style="font-weight:800;font-size:14px;">Salesman-wise Sales</div><div class="muted" style="font-size:11.5px;margin-bottom:10px;">Tax Invoice revenue by salesperson</div>` +
    (rows.length ? rows.map(r=>`
      <div style="margin-bottom:10px;">
        <div style="display:flex;justify-content:space-between;font-size:12px;font-weight:700;margin-bottom:4px;"><span>${escapeHtml(r.label)}</span><span>${fmt(r.value)} · ${r.invoices} inv.</span></div>
        <div style="height:8px;background:var(--bg-outer);border-radius:100px;"><div style="height:100%;width:${max>0?(r.value/max)*100:0}%;background:var(--navy);border-radius:100px;"></div></div>
      </div>`).join("") : `<div class="empty-hint">No sales recorded yet.</div>`);
}
/** Sales and purchases per State › City › Area, side by side.
 *
 *  Bars are scaled against the largest figure across BOTH columns, not each
 *  column's own maximum — otherwise a ₹5,000 purchase bar would look the same
 *  length as a ₹5,00,000 sales bar sitting next to it. */
async function renderAreaReport(body){
  const data = await api("GET","/reports/area-wise"+reportRangeQS());
  const rows = data.rows || [];
  const t = data.totals || {};
  const max = Math.max(1, ...rows.map(r=>Math.max(r.salesValue, r.purchaseValue)));

  const bar = (value, colour) =>
    `<div style="height:7px;background:var(--bg-outer);border-radius:100px;">
       <div style="height:100%;width:${(value/max)*100}%;background:${colour};border-radius:100px;"></div>
     </div>`;

  body.innerHTML =
    `<div style="font-weight:800;font-size:14px;">Area-wise Sales &amp; Purchase</div>
     <div class="muted" style="font-size:11.5px;margin-bottom:10px;">
       State &rsaquo; City &rsaquo; Location, from the area recorded on each bill</div>` +
    (rows.length ? rows.map(r=>`
      <div style="margin-bottom:14px;${r.state ? "" : "opacity:.72;"}">
        <div style="font-size:12.5px;font-weight:800;margin-bottom:5px;">${escapeHtml(r.label)}</div>
        <div style="display:flex;justify-content:space-between;font-size:11.5px;margin-bottom:3px;">
          <span class="muted">Sales</span>
          <span style="font-weight:700;">${fmt(r.salesValue)} · ${r.salesBills} bill${r.salesBills===1?"":"s"}</span>
        </div>
        ${bar(r.salesValue, "var(--navy)")}
        <div style="display:flex;justify-content:space-between;font-size:11.5px;margin:6px 0 3px;">
          <span class="muted">Purchase</span>
          <span style="font-weight:700;">${fmt(r.purchaseValue)} · ${r.purchaseBills} bill${r.purchaseBills===1?"":"s"}</span>
        </div>
        ${bar(r.purchaseValue, "var(--gold)")}
      </div>`).join("") : `<div class="empty-hint">Nothing in this period.</div>`) +
    (rows.length ? `
      <div class="list-row" style="border-top:2px solid var(--border);margin-top:4px;">
        <div class="row-title">Total</div>
        <div class="row-right"><div class="row-title">${fmt(t.salesValue)} sales</div>
          <div class="row-sub">${fmt(t.purchaseValue)} purchase</div></div>
      </div>` : "") +
    // Said plainly rather than left for the owner to work out from a gap in
    // the numbers: this is how much of the turnover has no area on it.
    (t.unrecordedSales > 0 ? `
      <p class="muted" style="font-size:11px;margin-top:10px;line-height:1.6;">
        ${fmt(t.unrecordedSales)} of sales carries no area — those bills were saved before the
        area field existed, or left blank. Set the Location / Area on the bill to move it onto a line above.
      </p>` : "");
}

async function renderLocationStockReport(body){
  const rows = await api("GET","/reports/stock-by-location");
  const codeIcon = code => code==="shop" ? "&#127978;" : code==="warehouse" ? "&#127974;" : "&#128230;";
  body.innerHTML = `<div style="font-weight:800;font-size:14px;">Shop / Warehouse Stock</div><div class="muted" style="font-size:11.5px;margin-bottom:10px;">Every product's quantity at each location</div>` +
    (rows.length ? rows.map(r=>`
      <div class="list-row"><div>
        <div class="row-title">${escapeHtml(r.label)}</div>
        <div class="row-sub">${escapeHtml(r.brand||"")}${r.byLocation.map(l=>` · ${codeIcon(l.code)} ${escapeHtml(l.name)}: ${l.quantity}`).join("")}</div>
      </div><div class="row-right row-title">Total: ${r.total}</div></div>
    `).join("") : `<div class="empty-hint">No products yet.</div>`);
}
/**
 * Balance Sheet — what the shop owns against what it owes.
 *
 * Deliberately shows Net Worth rather than a textbook "Assets = Liabilities +
 * Capital": this app has no capital account or expense ledger, so a balancing
 * figure would have to be invented. Every number below is one the data really
 * supports. Also always AS OF NOW — stock and party dues are running balances
 * with no dated ledger behind them, so a past-date version can't be honest.
 */
async function renderBalanceSheetReport(body){
  const d = await api("GET","/reports/balance-sheet");
  const row = (label, value, opts={}) => `
    <div style="display:flex;justify-content:space-between;gap:10px;padding:6px 0;${opts.border?"border-top:1px solid var(--border);":""}${opts.bold?"font-weight:800;":""}">
      <span${opts.dim?' class="muted"':""}>${escapeHtml(label)}</span><span>${fmt(value)}</span>
    </div>`;

  const a = d.assets, l = d.liabilities, c = d.capital, bc = d.balanceCheck;
  const head = t => `<div style="font-weight:800;font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted);margin-top:16px;">${t}</div>`;

  body.innerHTML = `
    <div style="font-weight:800;font-size:14px;">Balance Sheet</div>
    <div class="muted" style="font-size:11.5px;margin-bottom:12px;">Financial position as of ${escapeHtml(d.asOf)}</div>

    ${head("Assets — what you own")}
    ${row("Cash in Hand", a.cashInHand)}
    ${a.bankAccounts.length
      ? a.bankAccounts.map(b=>row("Bank — "+b.name, b.balance, {dim:true})).join("")
      : row("Bank", a.bankBalance, {dim:true})}
    ${row("Closing Stock (at cost)", a.closingStock)}
    ${row("Customer Receivables", a.receivables)}
    ${a.fixedAssets ? row("Fixed Assets (net of depreciation)", a.fixedAssets) : ""}
    ${a.securityDeposits ? row("Security Deposits", a.securityDeposits) : ""}
    ${a.gstInputCredit ? row("GST Input Credit", a.gstInputCredit) : ""}
    ${a.supplierAdvances ? row("Advances paid to Suppliers", a.supplierAdvances) : ""}
    ${row("Total Assets", a.total, {bold:true, border:true})}

    ${head("Liabilities — what you owe")}
    ${row("Supplier Payables", l.payables)}
    ${l.bankLoans ? row("Bank Loans", l.bankLoans) : ""}
    ${l.otherLiabilities ? row("Other Liabilities", l.otherLiabilities) : ""}
    ${Object.entries(l.outstandingByCategory||{}).map(([k,v])=>row(k, v, {dim:true})).join("")}
    ${l.gstPayable ? row("GST Payable", l.gstPayable) : ""}
    ${l.customerAdvances ? row("Advances received from Customers", l.customerAdvances) : ""}
    ${row("Total Liabilities", l.total, {bold:true, border:true})}

    ${head("Capital")}
    ${row("Opening Capital", c.opening)}
    ${c.introduced ? row("Add: Capital Introduced", c.introduced) : ""}
    ${c.drawings ? row("Less: Drawings", -c.drawings) : ""}
    ${row("Add: Retained Profit", c.retainedProfit, {dim:true})}
    ${row("Closing Capital", c.closing, {bold:true, border:true})}

    ${head("Balance check")}
    ${row("Total Assets", bc.totalAssets)}
    ${row("Total Liabilities + Capital", bc.liabilitiesPlusCapital)}
    <div style="margin-top:10px;padding:12px;border-radius:10px;background:${bc.balanced?"var(--ok-bg)":"var(--warn-bg)"};color:${bc.balanced?"var(--ok)":"var(--warn-text)"};">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;">
        <span style="font-weight:800;font-size:13px;">${bc.balanced ? "Balanced" : "Difference (Suspense)"}</span>
        <span style="font-weight:800;font-size:17px;">${bc.balanced ? "✓" : fmt(bc.difference)}</span>
      </div>
      ${bc.balanced ? "" : `<div style="font-size:11.5px;margin-top:6px;line-height:1.5;">
        Assets do not yet equal Liabilities + Capital. This gap is money the app
        cannot see — usually Opening Capital, fixed assets, loans or deposits not
        entered yet. Enter them under Settings → Opening Balances and this shrinks
        towards zero. It is shown rather than hidden on purpose: a sheet forced to
        balance would conceal exactly this.
      </div>`}
    </div>

    <div style="margin-top:14px;padding:12px;border-radius:10px;background:var(--bg-outer);display:flex;justify-content:space-between;align-items:center;gap:10px;">
      <span style="font-weight:800;font-size:13px;">Net Worth</span>
      <span style="font-weight:800;font-size:17px;color:${d.netWorth<0?"var(--danger)":"var(--ok)"};">${fmt(d.netWorth)}</span>
    </div>
    <div class="muted" style="font-size:11px;margin-top:8px;">Total Assets &minus; Total Liabilities.</div>

    ${d.stock.itemsWithoutCost ? `
      <div style="margin-top:12px;padding:10px;border-radius:9px;background:var(--warn-bg);color:var(--warn-text);font-size:11.5px;line-height:1.5;">
        <b>Closing Stock is understated.</b> ${d.stock.itemsWithoutCost} item${d.stock.itemsWithoutCost>1?"s":""}
        (${d.stock.unitsWithoutCost} unit${d.stock.unitsWithoutCost>1?"s":""}) ${d.stock.itemsWithoutCost>1?"have":"has"}
        no purchase cost on file and ${d.stock.itemsWithoutCost>1?"are":"is"} counted at zero.
      </div>` : ""}

    <div class="muted" style="font-size:11px;margin-top:12px;line-height:1.5;">
      Figures are as of today. Stock and party dues are running balances, so a
      past-dated Balance Sheet cannot be produced accurately.
    </div>`;
}

/**
 * Profit & Loss. Honest about its two weak points rather than presenting a
 * confident number: sales of products with no purchase cost on file overstate
 * profit, and uncategorised cash/bank movements can't be attributed properly.
 */
async function renderPnlReport(body){
  const p = await api("GET","/reports/pnl"+reportRangeQS());
  const row = (label, value, opts={}) => `
    <div style="display:flex;justify-content:space-between;gap:10px;padding:6px 0;${opts.border?"border-top:1px solid var(--border);":""}${opts.bold?"font-weight:800;":""}">
      <span${opts.dim?' class="muted"':""}>${escapeHtml(label)}</span><span>${fmt(value)}</span>
    </div>`;
  const head = t => `<div style="font-weight:800;font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:var(--muted);margin-top:16px;">${t}</div>`;
  const lines = obj => Object.entries(obj).filter(([,v])=>v>0).map(([k,v])=>row(k, v, {dim:true})).join("");

  body.innerHTML = `
    <div style="font-weight:800;font-size:14px;">Profit &amp; Loss</div>
    <div class="muted" style="font-size:11.5px;margin-bottom:12px;">${p.bills} tax invoice${p.bills===1?"":"s"} in this period</div>

    ${head("Income")}
    ${row("Sales Revenue (net of discount)", p.income.salesRevenue)}
    ${p.income.chargesRecovered ? row("Transport / Loading recovered", p.income.chargesRecovered) : ""}
    ${lines(p.income.otherIncome)}
    ${row("Total Income", p.income.total, {bold:true, border:true})}

    ${head("Expenses")}
    ${row("Cost of Goods Sold", p.expenses.costOfGoodsSold)}
    ${lines(p.expenses.operating)}
    ${row("Total Expenses", p.expenses.total, {bold:true, border:true})}

    <div style="margin-top:16px;display:grid;grid-template-columns:1fr 1fr;gap:10px;">
      <div style="padding:12px;border-radius:10px;background:var(--bg-outer);">
        <div class="muted" style="font-size:11px;">Gross Profit</div>
        <div style="font-weight:800;font-size:16px;">${fmt(p.grossProfit)}</div>
      </div>
      <div style="padding:12px;border-radius:10px;background:var(--bg-outer);">
        <div class="muted" style="font-size:11px;">Net Profit</div>
        <div style="font-weight:800;font-size:16px;color:${p.netProfit<0?"var(--danger)":"var(--ok)"};">${fmt(p.netProfit)}</div>
      </div>
    </div>

    ${p.itemsWithoutCost ? `
      <div style="margin-top:12px;padding:10px;border-radius:9px;background:var(--warn-bg);color:var(--warn-text);font-size:11.5px;line-height:1.5;">
        <b>Profit is overstated.</b> ${p.itemsWithoutCost} sold line${p.itemsWithoutCost>1?"s have":" has"} no
        purchase cost on file, so ${p.itemsWithoutCost>1?"they add":"it adds"} revenue with no matching cost.
        Record purchases for those products to get a true margin.
      </div>` : ""}

    <div class="muted" style="font-size:11px;margin-top:12px;line-height:1.5;">
      Customer and supplier payments are excluded — collecting a debt or paying a
      creditor moves money without earning or spending it. Cost of Goods Sold uses
      each product's latest purchase cost, the same basis as the Profit report.
    </div>`;
}

async function renderTransfersReport(body){
  const rows = await api("GET","/transfers"+reportRangeQS());
  body.innerHTML = `<div style="font-weight:800;font-size:14px;">Transfer History</div><div class="muted" style="font-size:11.5px;margin-bottom:10px;">Stock moved between locations, newest first</div>` +
    (rows.length ? rows.map(r=>{
      const fromName = (state.locations.find(l=>l.id===r.from_location_id)||{}).name || "?";
      const toName = (state.locations.find(l=>l.id===r.to_location_id)||{}).name || "?";
      return `<div class="list-row"><div>
        <div class="row-title">${escapeHtml(r.product_name)}${r.size_label?" · "+escapeHtml(r.size_label):""}</div>
        <div class="row-sub">${new Date(r.created_at).toLocaleDateString("en-IN")} · ${escapeHtml(fromName)} &rarr; ${escapeHtml(toName)}${r.staff_name?" · "+escapeHtml(r.staff_name):""}${r.reason?" · "+escapeHtml(r.reason):""}</div>
      </div><div class="row-right row-title">${r.quantity}</div></div>`;
    }).join("") : `<div class="empty-hint">No transfers recorded yet.</div>`);
}
